static PROVIDER_EDIT_CAPABILITIES: std::sync::LazyLock<
    std::sync::Mutex<std::collections::HashMap<String, ProviderEditCapability>>,
> = std::sync::LazyLock::new(|| std::sync::Mutex::new(std::collections::HashMap::new()));
const PROVIDER_EDIT_CAPABILITY_TTL: Duration = Duration::from_secs(30 * 60);
const PROVIDER_EDIT_CAPABILITY_CAPACITY: usize = 128;

/// Persist the exact config-only default-update terminal receipt before the
/// best-effort event fan-out. The event transport is intentionally ephemeral,
/// but its correlation is not: recovery and idempotent request replay consult
/// this immutable ledger before retiring the retained config journal.
async fn persist_and_broadcast_default_model_update_receipt(
    ctx: &DaemonContext,
    handle: &crate::daemon::session_worker::SessionWorkerHandle,
    default_update_id: uuid::Uuid,
    outcome: proto::DefaultModelStandaloneOutcome,
    authority: Option<&cockpit_config::config::effective_default::DefaultUpdateAuthorityBinding>,
) -> std::result::Result<
    Option<cockpit_config::config::effective_default::RetainedDefaultReceiptProof>,
    ErrorPayload,
> {
    let outcome_json = serde_json::to_string(&outcome).map_err(internal)?;
    let (authority_revision, config_generation) = match (&outcome, authority) {
        (
            proto::DefaultModelStandaloneOutcome::Applied {
                authority_revision, ..
            },
            Some(authority),
        ) if authority_revision == &authority.authority_revision => (
            Some(authority.authority_revision.clone()),
            Some(authority.config_generation),
        ),
        (proto::DefaultModelStandaloneOutcome::Applied { .. }, _) => {
            return Err(internal(
                "applied default-model receipt lacks its sealed retained authority binding",
            ));
        }
        // A recovery can determine that a committed/prepared operation was
        // restored rather than applied.  It still seals the same retained
        // authority before recording that rejection, so later cleanup/replay
        // cannot confuse A's failure with B's state.
        (proto::DefaultModelStandaloneOutcome::Rejected { .. }, Some(authority)) => (
            Some(authority.authority_revision.clone()),
            Some(authority.config_generation),
        ),
        (proto::DefaultModelStandaloneOutcome::Rejected { .. }, None) => (None, None),
    };
    let receipt_proof = authority
        .map(|authority| {
            cockpit_config::config::effective_default::RetainedDefaultReceiptProof::new(
                default_update_id,
                handle.session_id,
                authority.clone(),
                &outcome_json,
            )
        })
        .transpose()
        .map_err(internal)?;
    match ctx
        .db
        .record_default_model_update_receipt(
            handle.session_id,
            default_update_id,
            crate::db::session_log::DefaultModelUpdateReceipt {
                outcome_json,
                authority_revision,
                config_generation,
            },
        )
        .await
        .map_err(internal)?
    {
        crate::db::session_log::DefaultModelUpdateReceiptWrite::Recorded
        | crate::db::session_log::DefaultModelUpdateReceiptWrite::Existing { .. } => {
            // A replay deliberately re-publishes the same immutable outcome
            // with the same correlation id. Clients deduplicate that id;
            // retained-journal recovery itself only sends on `Recorded`.
            handle.broadcast_default_model_update_result(default_update_id, outcome);
        }
    }
    Ok(receipt_proof)
}

fn decode_default_model_update_receipt(
    outcome_json: &str,
) -> std::result::Result<proto::DefaultModelStandaloneOutcome, ErrorPayload> {
    serde_json::from_str(outcome_json).map_err(|_| ErrorPayload {
        code: ErrorCode::Internal,
        message: "stored default-model terminal receipt is invalid".into(),
    })
}

fn receipt_matches_default_update_authority(
    receipt: &crate::db::session_log::DefaultModelUpdateReceipt,
    authority: &cockpit_config::config::effective_default::DefaultUpdateAuthorityBinding,
) -> bool {
    match (&receipt.authority_revision, receipt.config_generation) {
        // A rejected pre-mutation request has no retained authority result to
        // bind and can be replayed as its immutable rejection.
        (None, None) => true,
        (Some(revision), Some(generation)) => {
            revision == &authority.authority_revision && generation == authority.config_generation
        }
        // SQLite's table constraint makes this unreachable for new rows, but
        // fail closed if a corrupt/hand-authored database ever contains it.
        _ => false,
    }
}

/// A retained `receipt_emitted` marker is workspace-controlled metadata, not
/// proof of a daemon receipt. Accept it only when the immutable session ledger
/// has the same canonical protocol outcome and the exact A-bound authority.
fn retained_receipt_proof_matches_ledger(
    proof: &cockpit_config::config::effective_default::RetainedDefaultReceiptProof,
    receipt: &crate::db::session_log::DefaultModelUpdateReceipt,
) -> bool {
    if !matches!(
        (&receipt.authority_revision, receipt.config_generation),
        (Some(revision), Some(generation))
            if revision == &proof.authority().authority_revision
                && generation == proof.authority().config_generation
    ) {
        return false;
    }
    let Ok(outcome) =
        serde_json::from_str::<proto::DefaultModelStandaloneOutcome>(&receipt.outcome_json)
    else {
        return false;
    };
    let Ok(canonical_outcome_json) = serde_json::to_string(&outcome) else {
        return false;
    };
    if let proto::DefaultModelStandaloneOutcome::Applied {
        authority_revision,
        generation,
        ..
    } = &outcome
        && (authority_revision != &proof.authority().authority_revision
            || *generation != proof.authority().config_generation)
    {
        return false;
    }
    receipt.outcome_json == canonical_outcome_json
        && proof.matches_canonical_outcome_json(&canonical_outcome_json)
}

pub(super) async fn validate_retained_receipt_proof_against_ledger(
    ctx: &DaemonContext,
    proof: &cockpit_config::config::effective_default::RetainedDefaultReceiptProof,
) -> anyhow::Result<()> {
    let receipt = ctx
        .db
        .default_model_update_receipt(proof.session_id(), proof.default_update_id())
        .await
        .context("looking up retained default receipt for journal cleanup")?
        .context("retained receipt-emitted journal has no durable terminal receipt")?;
    anyhow::ensure!(
        retained_receipt_proof_matches_ledger(proof, &receipt),
        "retained receipt-emitted journal does not match its durable terminal receipt"
    );
    Ok(())
}

async fn retained_receipt_proof_from_ledger(
    ctx: &DaemonContext,
    session_id: uuid::Uuid,
    default_update_id: uuid::Uuid,
    authority: &cockpit_config::config::effective_default::DefaultUpdateAuthorityBinding,
) -> anyhow::Result<cockpit_config::config::effective_default::RetainedDefaultReceiptProof> {
    let receipt = ctx
        .db
        .default_model_update_receipt(session_id, default_update_id)
        .await
        .context("looking up recorded retained default receipt")?
        .context("retained default receipt was not durably recorded")?;
    anyhow::ensure!(
        matches!(
            (&receipt.authority_revision, receipt.config_generation),
            (Some(revision), Some(generation))
                if revision == &authority.authority_revision
                    && generation == authority.config_generation
        ),
        "recorded retained default receipt has a different authority binding"
    );
    let outcome =
        serde_json::from_str::<proto::DefaultModelStandaloneOutcome>(&receipt.outcome_json)
            .context("recorded retained default receipt is not a protocol outcome")?;
    let canonical_outcome_json = serde_json::to_string(&outcome)
        .context("serializing recorded retained default receipt canonically")?;
    anyhow::ensure!(
        receipt.outcome_json == canonical_outcome_json,
        "recorded retained default receipt is not canonical JSON"
    );
    if let proto::DefaultModelStandaloneOutcome::Applied {
        authority_revision,
        generation,
        ..
    } = &outcome
    {
        anyhow::ensure!(
            authority_revision == &authority.authority_revision
                && *generation == authority.config_generation,
            "recorded retained default receipt outcome has a different authority binding"
        );
    }
    cockpit_config::config::effective_default::RetainedDefaultReceiptProof::new(
        default_update_id,
        session_id,
        authority.clone(),
        &canonical_outcome_json,
    )
}

fn bind_recovered_default_update_authority(
    recovered: &mut [crate::config::providers::RecoveredTransaction],
    authority: cockpit_config::config::effective_default::DefaultUpdateAuthorityBinding,
) -> anyhow::Result<()> {
    for transaction in recovered {
        transaction.correlation = transaction
            .correlation
            .with_default_update_authority(authority.clone())?;
    }
    Ok(())
}

/// Finalize a retained config-only transaction off the async runtime.  In a
/// daemon unit test the crash seam is armed on the request task, whereas the
/// blocking filesystem finalizer necessarily runs on a Tokio worker thread;
/// explicitly propagate that test-only seam so the post-receipt crash window
/// is exercised at the real finalization boundary. Production contains no
/// seam propagation or mutable test state.
async fn finalize_retained_default_after_terminal_receipt(
    finalization: cockpit_config::config::effective_default::RetainedEffectiveDefaultPendingFinalization,
    receipt_proof: cockpit_config::config::effective_default::RetainedDefaultReceiptProof,
) -> std::result::Result<anyhow::Result<()>, tokio::task::JoinError> {
    #[cfg(test)]
    let crash_point = cockpit_config::config::effective_default::current_crash_inject_for_tests();
    tokio::task::spawn_blocking(move || {
        #[cfg(test)]
        {
            cockpit_config::config::effective_default::with_crash_inject_for_tests(
                crash_point,
                || finalization.finalize_after_terminal_receipt(&receipt_proof),
            )
        }
        #[cfg(not(test))]
        {
            finalization.finalize_after_terminal_receipt(&receipt_proof)
        }
    })
    .await
}

/// Recover a capability-backed default-model journal only after the exact
/// worker attachment (and therefore its `WorkerWorkspaceConfigAuthority`) is
/// live. Ambient startup recovery deliberately cannot safely rediscover an
/// explicit/retained target: it leaves these journals pending until this
/// point. The recovered filesystem outcome is published through this worker,
/// then durably receipted, before its private artifacts are retired.
async fn recover_retained_defaults_for_attached_worker(
    ctx: &DaemonContext,
    handle: &crate::daemon::session_worker::SessionWorkerHandle,
) -> anyhow::Result<()> {
    // Recovery ultimately asks the live worker to publish a retained
    // snapshot. Do not hold CONFIG_PUBLICATION across that await: a queued
    // driver model persistence may need the same coordinator before it can
    // service the replacement. The retained target lock plus generation and
    // trust-revision CAS below provide the ordering/freshness fences.
    let policy =
        crate::config::trust::resolve_workspace_trust_policy_from_db(&ctx.db, &handle.project_root)
            .await?;
    let target = match handle
        .workspace_root_authority
        .retained_effective_default_target_for_policy(&policy)
    {
        Ok(target) => target,
        // No writable retained layer is an ordinary attach state, not a
        // reason to make a worker unavailable.
        Err(_) => return Ok(()),
    };
    let recovery = tokio::task::spawn_blocking(move || {
        cockpit_config::config::effective_default::recover_retained_effective_default_journal(
            &target,
        )
    })
    .await
    .context("joining retained effective-default recovery")??;
    let (mut recovered, mut finalization, receipt_validation) = recovery.into_parts();
    if let Some(receipt_validation) = receipt_validation {
        if receipt_validation.proof().session_id() != handle.session_id {
            anyhow::bail!(
                "retained receipt-emitted journal belongs to a different session; leaving it pending"
            );
        }
        // Never let a config-side ReceiptEmitted marker clean itself up. The
        // attached daemon must prove this exact journal claim against its
        // immutable ledger row before it can retire capability-private files.
        validate_retained_receipt_proof_against_ledger(ctx, receipt_validation.proof()).await?;
        let receipt_proof = receipt_validation.proof().clone();
        finalize_retained_default_after_terminal_receipt(
            receipt_validation.into_finalization(),
            receipt_proof,
        )
        .await
        .context("joining retained receipt-emitted journal finalizer")??;
        return Ok(());
    }
    if recovered.is_empty() {
        return Ok(());
    }
    if recovered
        .iter()
        .any(|transaction| transaction.correlation.session_id() != handle.session_id)
    {
        anyhow::bail!(
            "retained effective-default journal belongs to a different session; leaving it pending"
        );
    }

    // A previous completion may already have sealed A. Do not derive a new
    // receipt authority from this attach's in-memory generation: the sealed
    // A binding is the only valid historical terminal identity.
    let sealed_authority = recovered
        .first()
        .and_then(|transaction| transaction.correlation.default_update_authority())
        .cloned();
    if recovered.iter().any(|transaction| {
        transaction.correlation.default_update_authority().cloned() != sealed_authority
    }) {
        anyhow::bail!("retained effective-default journal contains inconsistent authority seals");
    }

    let refresh =
        crate::daemon::config_refresh::refresh_session_config_after_retained_default_mutation(
            &ctx.db,
            ctx.config_source(),
            handle,
        )
        .await
        .map_err(|error| {
            anyhow::anyhow!("retained recovery could not refresh attached worker: {error:?}")
        })?;
    let selection = handle.config_snapshot().providers.active_model;
    let recovered_generation = sealed_authority
        .as_ref()
        .map(|authority| authority.config_generation)
        .unwrap_or(refresh.applied_generation);
    for transaction in &mut recovered {
        match &mut transaction.outcome {
            crate::config::providers::RecoveredOutcome::Applied {
                selection: recovered_selection,
                generation,
            } => {
                *recovered_selection = selection.clone();
                // A sealed transaction remains historically A-bound across
                // restart; never synthesize a new worker/active-model
                // generation while recovering it.
                *generation = recovered_generation;
            }
            crate::config::providers::RecoveredOutcome::Restored { restored, .. } => {
                *restored = selection.clone();
            }
        }
    }

    let authority = match sealed_authority {
        Some(authority) => {
            handle
                .workspace_root_authority
                .verify_retained_config_source_chain_for_policy(&policy)?;
            let policy_authority = handle
                .workspace_root_authority
                .retained_effective_default_authority_binding_for_policy(
                    &policy,
                    authority.config_generation,
                )?;
            if policy_authority.authority_revision != authority.authority_revision {
                anyhow::bail!(
                    "retained default journal is sealed for a source excluded by the current workspace trust policy; leaving it pending"
                );
            }
            authority
        }
        None => {
            let authority = handle
                .workspace_root_authority
                .retained_effective_default_authority_binding_for_policy(
                    &policy,
                    refresh.applied_generation,
                )?;
            let Some(finalization) = finalization.as_mut() else {
                anyhow::bail!("unsealed retained recovery lost its finalization token");
            };
            finalization.bind_default_update_authority(authority.clone())?;
            bind_recovered_default_update_authority(&mut recovered, authority.clone())?;
            authority
        }
    };
    let receipt_update_id = recovered
        .first()
        .and_then(|transaction| match &transaction.correlation {
            crate::config::providers::TransactionCorrelation::RetainedDefaultUpdate {
                default_update_id,
                ..
            } => Some(*default_update_id),
            _ => None,
        })
        .context("retained recovery lost its default-update correlation")?;
    crate::daemon::effective_default_recovery::deliver_retained_default_terminals(ctx, recovered)
        .await?;
    if let Some(finalization) = finalization.take() {
        let proof = retained_receipt_proof_from_ledger(
            ctx,
            handle.session_id,
            receipt_update_id,
            &authority,
        )
        .await?;
        finalize_retained_default_after_terminal_receipt(finalization, proof)
            .await
            .context("joining retained default receipt finalizer")??;
    }
    Ok(())
}

#[derive(serde::Serialize, serde::Deserialize)]
struct McpOAuthPending {
    project_root: String,
    server: String,
    #[serde(default = "default_mcp_profile")]
    profile: String,
    flow: McpOAuthPendingFlow,
}

#[derive(serde::Serialize, serde::Deserialize)]
#[serde(tag = "grant", rename_all = "snake_case")]
enum McpOAuthPendingFlow {
    Browser(crate::mcp::auth::McpOAuthFlow),
    Device {
        oauth: crate::mcp::config::OauthAuth,
        device_code: SealedOAuthText,
        interval_secs: u64,
        expires_in_secs: u64,
        user_code: SealedOAuthText,
        verification_uri: String,
        verification_uri_complete: String,
    },
}

fn default_mcp_profile() -> String {
    crate::mcp::config::DEFAULT_PROFILE.to_string()
}

fn mcp_pending_device_display(
    pending: &McpOAuthPending,
) -> (Option<String>, Option<String>, Option<String>) {
    match &pending.flow {
        McpOAuthPendingFlow::Device {
            user_code,
            verification_uri,
            verification_uri_complete,
            ..
        } => (
            Some(user_code.expose().to_string()),
            Some(verification_uri.clone()),
            Some(verification_uri_complete.clone()),
        ),
        McpOAuthPendingFlow::Browser(_) => (None, None, None),
    }
}

#[derive(Clone, serde::Serialize, serde::Deserialize)]
#[serde(transparent)]
struct SealedOAuthText(String);

impl SealedOAuthText {
    fn expose(&self) -> &str {
        &self.0
    }
}

impl From<String> for SealedOAuthText {
    fn from(value: String) -> Self {
        Self(value)
    }
}

impl Drop for SealedOAuthText {
    fn drop(&mut self) {
        zeroize::Zeroize::zeroize(&mut self.0);
    }
}

impl std::fmt::Debug for SealedOAuthText {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str("[REDACTED]")
    }
}

#[derive(Clone)]
enum ProviderOAuthFlow {
    /// A flow that has not started its one-time provider exchange.
    Ready(ProviderOAuthReady),
    /// A flow is never left in this state in the map: claiming it removes the
    /// Ready value before network I/O. The variant documents the state machine
    /// and makes accidental re-insertion of an in-flight flow conspicuous.
    #[allow(dead_code)]
    Completing {
        cancelled: std::sync::Arc<std::sync::atomic::AtomicBool>,
    },
}

#[derive(Clone, serde::Serialize, serde::Deserialize)]
enum ProviderOAuthReady {
    #[cfg(feature = "grok-subscription")]
    Grok(crate::auth::xai_oauth::ManualLogin),
    Codex(crate::auth::codex_oauth::DeviceLogin),
    Descriptor(DescriptorOAuthLogin),
}

#[derive(Clone, serde::Serialize, serde::Deserialize)]
struct DescriptorOAuthLogin {
    provider_id: String,
    login: DescriptorOAuthLoginState,
}

#[derive(Clone, serde::Serialize, serde::Deserialize)]
#[serde(tag = "flow", rename_all = "snake_case")]
enum DescriptorOAuthLoginState {
    DeviceCode(crate::auth::descriptor::DeviceCodeLogin),
    PkceBrowser(crate::auth::descriptor::PkceBrowserLogin),
}

#[derive(serde::Serialize, serde::Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
enum DurableOAuthFlow {
    Provider {
        owner: String,
        begin_client_operation_id: String,
        begin_request_hash: [u8; 32],
        begin_fencing_generation: i64,
        authorize_url: SealedOAuthText,
        user_code: Option<SealedOAuthText>,
        ready: ProviderOAuthReady,
        created_at_unix_ms: i64,
        expires_at_unix_ms: i64,
    },
    ProviderExchanging {
        owner: String,
        begin_client_operation_id: String,
        provider_id: String,
        completion_client_operation_id: String,
        completion_request_hash: [u8; 32],
        completion_fencing_generation: i64,
        claimed_at_unix_ms: i64,
        expires_at_unix_ms: i64,
    },
    Mcp {
        owner: String,
        begin_client_operation_id: String,
        begin_request_hash: [u8; 32],
        begin_fencing_generation: i64,
        authorize_url: SealedOAuthText,
        pending: McpOAuthPending,
        created_at_unix_ms: i64,
        expires_at_unix_ms: i64,
    },
    McpExchanging {
        owner: String,
        begin_client_operation_id: String,
        project_root: String,
        server: String,
        completion_client_operation_id: String,
        completion_request_hash: [u8; 32],
        completion_fencing_generation: i64,
        claimed_at_unix_ms: i64,
    },
    ProviderCommitted {
        owner: String,
        begin_client_operation_id: String,
        provider_id: String,
        completion_client_operation_id: String,
        completion_request_hash: [u8; 32],
        completion_fencing_generation: i64,
        terminal_response: Box<Response>,
        committed_at_unix_ms: i64,
    },
    McpCommitted {
        owner: String,
        begin_client_operation_id: String,
        project_root: String,
        server: String,
        completion_client_operation_id: String,
        completion_request_hash: [u8; 32],
        completion_fencing_generation: i64,
        terminal_response: Box<Response>,
        committed_at_unix_ms: i64,
    },
    /// Secret-free tombstone retained solely so an exact begin retry receives
    /// the same terminal expiry instead of replaying stale authorize data.
    Expired {
        owner: String,
        begin_client_operation_id: String,
        terminal_error: ErrorPayload,
        expired_at_unix_ms: i64,
    },
    Cancelled {
        owner: String,
        begin_client_operation_id: String,
        terminal_error: ErrorPayload,
        cancelled_at_unix_ms: i64,
    },
}

impl std::fmt::Debug for DurableOAuthFlow {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        let kind = match self {
            Self::Provider { .. } => "Provider",
            Self::ProviderExchanging { .. } => "ProviderExchanging",
            Self::Mcp { .. } => "Mcp",
            Self::McpExchanging { .. } => "McpExchanging",
            Self::ProviderCommitted { .. } => "ProviderCommitted",
            Self::McpCommitted { .. } => "McpCommitted",
            Self::Expired { .. } => "Expired",
            Self::Cancelled { .. } => "Cancelled",
        };
        formatter
            .debug_struct("DurableOAuthFlow")
            .field("kind", &kind)
            .field("payload", &"[REDACTED]")
            .finish()
    }
}

fn oauth_wall_ms() -> i64 {
    chrono::Utc::now().timestamp_millis()
}

fn oauth_expiry_ms(created_at_unix_ms: i64) -> i64 {
    created_at_unix_ms.saturating_add(i64::try_from(OAUTH_FLOW_TTL.as_millis()).unwrap_or(i64::MAX))
}

fn durable_oauth_expired(flow: &DurableOAuthFlow, now_unix_ms: i64) -> bool {
    match flow {
        DurableOAuthFlow::Provider {
            expires_at_unix_ms, ..
        }
        | DurableOAuthFlow::Mcp {
            expires_at_unix_ms, ..
        } => now_unix_ms >= *expires_at_unix_ms,
        DurableOAuthFlow::ProviderExchanging {
            expires_at_unix_ms, ..
        } => now_unix_ms >= *expires_at_unix_ms,
        DurableOAuthFlow::McpExchanging {
            claimed_at_unix_ms, ..
        } => now_unix_ms >= oauth_expiry_ms(*claimed_at_unix_ms),
        DurableOAuthFlow::ProviderCommitted {
            committed_at_unix_ms,
            ..
        }
        | DurableOAuthFlow::McpCommitted {
            committed_at_unix_ms,
            ..
        } => now_unix_ms >= oauth_expiry_ms(*committed_at_unix_ms),
        DurableOAuthFlow::Expired { .. } | DurableOAuthFlow::Cancelled { .. } => true,
    }
}

fn durable_oauth_owner_and_created(flow: &DurableOAuthFlow) -> (&str, i64) {
    match flow {
        DurableOAuthFlow::Provider {
            owner,
            created_at_unix_ms,
            ..
        }
        | DurableOAuthFlow::Mcp {
            owner,
            created_at_unix_ms,
            ..
        } => (owner, *created_at_unix_ms),
        DurableOAuthFlow::ProviderExchanging {
            owner,
            claimed_at_unix_ms,
            ..
        }
        | DurableOAuthFlow::McpExchanging {
            owner,
            claimed_at_unix_ms,
            ..
        } => (owner, *claimed_at_unix_ms),
        DurableOAuthFlow::ProviderCommitted {
            owner,
            committed_at_unix_ms,
            ..
        }
        | DurableOAuthFlow::McpCommitted {
            owner,
            committed_at_unix_ms,
            ..
        } => (owner, *committed_at_unix_ms),
        DurableOAuthFlow::Expired {
            owner,
            expired_at_unix_ms,
            ..
        } => (owner, *expired_at_unix_ms),
        DurableOAuthFlow::Cancelled {
            owner,
            cancelled_at_unix_ms,
            ..
        } => (owner, *cancelled_at_unix_ms),
    }
}

async fn expire_ready_oauth_flow(
    ctx: &DaemonContext,
    flow_id: String,
    owner: String,
    begin_client_operation_id: String,
    begin_request_hash: [u8; 32],
    begin_fencing_generation: i64,
) -> std::result::Result<(), ErrorPayload> {
    let terminal_error = ErrorPayload {
        code: ErrorCode::Conflict,
        message: "the OAuth flow expired before completion; start a new login".to_owned(),
    };
    let expired_at_unix_ms = oauth_wall_ms();
    let tombstone = zeroize::Zeroizing::new(
        serde_json::to_vec(&DurableOAuthFlow::Expired {
            owner: owner.clone(),
            begin_client_operation_id: begin_client_operation_id.clone(),
            terminal_error,
            expired_at_unix_ms,
        })
        .map_err(internal)?,
    );
    let vault = ctx.secret_vault.clone();
    let vault_id = oauth_flow_vault_id(&flow_id);
    ctx.db
        .transaction(move |conn| {
            // Re-read under the writer transaction so a concurrently claimed
            // flow cannot be erased by an expiry decision made from a stale
            // snapshot.
            let bytes = vault
                .get_item_on_conn(
                    conn,
                    cockpit_db::secret_vault::SecretVaultKind::SealedState,
                    &vault_id,
                )
                .map_err(|error| anyhow::anyhow!(error))?;
            let marker: DurableOAuthFlow = serde_json::from_slice(bytes.as_slice())?;
            let still_exact_expired_ready = match marker {
                DurableOAuthFlow::Provider {
                    owner: marker_owner,
                    begin_client_operation_id: marker_operation_id,
                    begin_request_hash: marker_hash,
                    begin_fencing_generation: marker_fence,
                    expires_at_unix_ms,
                    ..
                }
                | DurableOAuthFlow::Mcp {
                    owner: marker_owner,
                    begin_client_operation_id: marker_operation_id,
                    begin_request_hash: marker_hash,
                    begin_fencing_generation: marker_fence,
                    expires_at_unix_ms,
                    ..
                } => {
                    marker_owner == owner
                        && marker_operation_id == begin_client_operation_id
                        && marker_hash == begin_request_hash
                        && marker_fence == begin_fencing_generation
                        && oauth_wall_ms() >= expires_at_unix_ms
                }
                _ => false,
            };
            if !still_exact_expired_ready {
                return Ok(());
            }
            // Begin receipts are already terminal-success and terminal rows
            // are immutable by schema. Verify that exact receipt, then replace
            // the secret-bearing Ready payload with a secret-free expiry
            // tombstone that makes future begin retries deterministic.
            let receipt_exists: bool = conn.query_row(
                "SELECT EXISTS(SELECT 1 FROM local_operation_receipts
                 WHERE owner_digest=?1 AND client_operation_id=?2
                   AND request_hash=?3 AND fencing_generation=?4
                   AND state='terminal_success')",
                rusqlite::params![
                    owner,
                    begin_client_operation_id,
                    begin_request_hash.as_slice(),
                    begin_fencing_generation
                ],
                |row| row.get(0),
            )?;
            if !receipt_exists {
                anyhow::bail!("expired OAuth flow has no exact replay receipt");
            }
            vault
                .mutate_item_on_conn(
                    conn,
                    cockpit_db::secret_vault::SecretVaultKind::SealedState,
                    &vault_id,
                    Some(tombstone.as_slice()),
                )
                .map_err(|error| anyhow::anyhow!(error))?;
            Ok(())
        })
        .await
        .map_err(internal)
}

async fn purge_durable_oauth_flows(
    ctx: &DaemonContext,
    admitting_owner: &str,
) -> std::result::Result<(), ErrorPayload> {
    let mut flows = Vec::new();
    for item_id in ctx
        .secret_vault
        .list_item_ids(cockpit_db::secret_vault::SecretVaultKind::SealedState)
        .map_err(|error| internal(anyhow::anyhow!(error)))?
        .into_iter()
        .filter(|id| id.starts_with("oauth-flow:"))
    {
        let flow_id = item_id.trim_start_matches("oauth-flow:").to_owned();
        if let Some(flow) = load_oauth_flow(ctx, &flow_id)? {
            if let DurableOAuthFlow::Expired {
                owner,
                begin_client_operation_id,
                ..
            }
            | DurableOAuthFlow::Cancelled {
                owner,
                begin_client_operation_id,
                ..
            } = &flow
            {
                // Secret-free terminal tombstones do not consume live-flow
                // capacity. Once the owning receipt reaches normal retention,
                // the tombstone no longer has a retry identity and can go too.
                if ctx
                    .db
                    .local_operation_settlement(owner.clone(), begin_client_operation_id.clone())
                    .await
                    .map_err(internal)?
                    .is_none()
                {
                    delete_oauth_flow(ctx, &flow_id)?;
                }
                continue;
            }
            let (owner, created) = durable_oauth_owner_and_created(&flow);
            let begin_identity = match &flow {
                DurableOAuthFlow::Provider {
                    begin_client_operation_id,
                    begin_request_hash,
                    begin_fencing_generation,
                    ..
                }
                | DurableOAuthFlow::Mcp {
                    begin_client_operation_id,
                    begin_request_hash,
                    begin_fencing_generation,
                    ..
                } => Some((
                    begin_client_operation_id.clone(),
                    *begin_request_hash,
                    *begin_fencing_generation,
                )),
                DurableOAuthFlow::ProviderExchanging { .. }
                | DurableOAuthFlow::McpExchanging { .. }
                | DurableOAuthFlow::ProviderCommitted { .. }
                | DurableOAuthFlow::McpCommitted { .. }
                | DurableOAuthFlow::Expired { .. }
                | DurableOAuthFlow::Cancelled { .. } => None,
            };
            let receipt_protected = if let Some((operation_id, _, _)) = &begin_identity {
                ctx.db
                    .local_operation_settlement(owner.to_owned(), operation_id.clone())
                    .await
                    .map_err(internal)?
                    .is_some()
            } else {
                true
            };
            let ready = matches!(
                &flow,
                DurableOAuthFlow::Provider { .. } | DurableOAuthFlow::Mcp { .. }
            );
            flows.push((
                flow_id,
                owner.to_owned(),
                created,
                ready,
                receipt_protected,
                durable_oauth_expired(&flow, oauth_wall_ms()),
                begin_identity,
            ));
        }
    }
    flows.sort_by_key(|(_, _, created, _, _, _, _)| *created);

    // A Ready flow has a hard device-code-compatible lifetime. Its begin receipt is
    // rewritten to the exact terminal expiry outcome in the same transaction
    // that removes the sealed verifier, so an abandoned receipt cannot protect
    // capacity forever or replay a dead authorize instruction.
    for (flow_id, owner, _, ready, _, expired, begin_identity) in &flows {
        if *ready && *expired {
            let (operation_id, request_hash, fence) = begin_identity
                .clone()
                .ok_or_else(|| internal(anyhow::anyhow!("Ready OAuth flow lost begin identity")))?;
            expire_ready_oauth_flow(
                ctx,
                flow_id.clone(),
                owner.clone(),
                operation_id,
                request_hash,
                fence,
            )
            .await?;
        }
    }
    flows.retain(|(_, _, _, ready, _, expired, _)| !(*ready && *expired));
    let owner_excess = flows
        .iter()
        .filter(|(_, owner, _, _, _, _, _)| owner == admitting_owner)
        .count()
        .saturating_sub(OAUTH_FLOW_OWNER_CAPACITY.saturating_sub(1));
    let global_excess = flows
        .len()
        .saturating_sub(OAUTH_FLOW_GLOBAL_CAPACITY.saturating_sub(1));
    let mut owner_removed = 0usize;
    let mut global_removed = 0usize;
    for (flow_id, owner, _, ready, receipt_protected, _, _) in flows {
        let remove_for_owner = owner == admitting_owner && owner_removed < owner_excess;
        let remove_for_global = global_removed < global_excess;
        if (remove_for_owner || remove_for_global) && ready && !receipt_protected {
            delete_oauth_flow(ctx, &flow_id)?;
            owner_removed += usize::from(remove_for_owner);
            global_removed += 1;
        }
    }
    if owner_removed < owner_excess || global_removed < global_excess {
        return Err(conflict(
            "OAuth flow capacity is occupied by unsettled or replay-protected operations",
        ));
    }
    Ok(())
}

/// Periodic expiry for daemon-owned OAuth authority.
///
/// This path never admits a new flow and never time-takes over an exchange.
/// It only (a) converts an exact expired Ready marker to its receipt-bound,
/// secret-free tombstone and (b) deletes terminal tombstones after their
/// owning begin receipt has itself been retired. Thus an abandoned PKCE
/// verifier/device state cannot live until the next Begin request, while an
/// exact retry retains deterministic settlement for as long as its receipt.
pub(super) async fn maintain_durable_oauth_flows(
    ctx: &DaemonContext,
) -> std::result::Result<(), ErrorPayload> {
    ctx.oauth_flows.maintain().await;
    for item_id in ctx
        .secret_vault
        .list_item_ids(cockpit_db::secret_vault::SecretVaultKind::SealedState)
        .map_err(|error| internal(anyhow::anyhow!(error)))?
        .into_iter()
        .filter(|id| id.starts_with("oauth-flow:"))
    {
        let flow_id = item_id.trim_start_matches("oauth-flow:").to_owned();
        let Some(flow) = load_oauth_flow(ctx, &flow_id)? else {
            continue;
        };
        match flow {
            DurableOAuthFlow::Provider {
                owner,
                begin_client_operation_id,
                begin_request_hash,
                begin_fencing_generation,
                expires_at_unix_ms,
                ..
            }
            | DurableOAuthFlow::Mcp {
                owner,
                begin_client_operation_id,
                begin_request_hash,
                begin_fencing_generation,
                expires_at_unix_ms,
                ..
            } if oauth_wall_ms() >= expires_at_unix_ms => {
                expire_ready_oauth_flow(
                    ctx,
                    flow_id,
                    owner,
                    begin_client_operation_id,
                    begin_request_hash,
                    begin_fencing_generation,
                )
                .await?;
            }
            DurableOAuthFlow::Expired {
                owner,
                begin_client_operation_id,
                ..
            }
            | DurableOAuthFlow::Cancelled {
                owner,
                begin_client_operation_id,
                ..
            } => {
                let receipt = ctx
                    .db
                    .local_operation_settlement(owner, begin_client_operation_id)
                    .await
                    .map_err(internal)?;
                if receipt.is_none() {
                    delete_oauth_flow(ctx, &flow_id)?;
                }
            }
            // Exchanging and committed markers are recovery evidence. Their
            // exact receipt transition, not elapsed wall time, owns cleanup.
            _ => {}
        }
    }
    Ok(())
}

fn find_durable_oauth_flow(
    ctx: &DaemonContext,
    owner: &str,
    begin_client_operation_id: &str,
) -> std::result::Result<Option<(String, DurableOAuthFlow)>, ErrorPayload> {
    for item_id in ctx
        .secret_vault
        .list_item_ids(cockpit_db::secret_vault::SecretVaultKind::SealedState)
        .map_err(|error| internal(anyhow::anyhow!(error)))?
        .into_iter()
        .filter(|id| id.starts_with("oauth-flow:"))
    {
        let flow_id = item_id.trim_start_matches("oauth-flow:").to_owned();
        let Some(flow) = load_oauth_flow(ctx, &flow_id)? else {
            continue;
        };
        let matches_begin = match &flow {
            DurableOAuthFlow::Provider {
                owner: durable_owner,
                begin_client_operation_id: durable_begin,
                ..
            }
            | DurableOAuthFlow::Mcp {
                owner: durable_owner,
                begin_client_operation_id: durable_begin,
                ..
            } => durable_owner == owner && durable_begin == begin_client_operation_id,
            _ => false,
        };
        if matches_begin {
            return Ok(Some((flow_id, flow)));
        }
    }
    Ok(None)
}

fn oauth_flow_vault_id(flow_id: &str) -> String {
    format!("oauth-flow:{flow_id}")
}

async fn claim_oauth_exchange(
    ctx: &DaemonContext,
    flow_id: String,
    owner: String,
    begin_client_operation_id: String,
    completion_client_operation_id: String,
    completion_request_hash: [u8; 32],
    completion_fencing_generation: i64,
    exchanging: DurableOAuthFlow,
) -> std::result::Result<(), ErrorPayload> {
    let bytes = zeroize::Zeroizing::new(serde_json::to_vec(&exchanging).map_err(internal)?);
    let vault = ctx.secret_vault.clone();
    let vault_id = oauth_flow_vault_id(&flow_id);
    ctx.db
        .transaction(move |conn| {
            let current = vault
                .get_item_on_conn(
                    conn,
                    cockpit_db::secret_vault::SecretVaultKind::SealedState,
                    &vault_id,
                )
                .map_err(|error| anyhow::anyhow!(error))?;
            let current: DurableOAuthFlow = serde_json::from_slice(current.as_slice())?;
            let exact_live_ready = match (&current, &exchanging) {
                (
                    DurableOAuthFlow::Provider {
                        owner: current_owner,
                        begin_client_operation_id: current_begin,
                        expires_at_unix_ms,
                        ..
                    },
                    DurableOAuthFlow::ProviderExchanging { .. },
                )
                | (
                    DurableOAuthFlow::Mcp {
                        owner: current_owner,
                        begin_client_operation_id: current_begin,
                        expires_at_unix_ms,
                        ..
                    },
                    DurableOAuthFlow::McpExchanging { .. },
                ) => {
                    current_owner == &owner
                        && current_begin == &begin_client_operation_id
                        && oauth_wall_ms() < *expires_at_unix_ms
                }
                _ => false,
            };
            if !exact_live_ready {
                anyhow::bail!("OAuth flow is not an exact live Ready claim");
            }
            let receipt_exists: bool = conn.query_row(
                "SELECT EXISTS(SELECT 1 FROM local_operation_receipts
                 WHERE owner_digest=?1 AND client_operation_id=?2
                   AND request_hash=?3 AND fencing_generation=?4
                   AND state='executing')",
                rusqlite::params![
                    owner,
                    completion_client_operation_id,
                    completion_request_hash.as_slice(),
                    completion_fencing_generation
                ],
                |row| row.get(0),
            )?;
            if !receipt_exists {
                anyhow::bail!("OAuth exchange lost its exact completion receipt");
            }
            vault
                .mutate_item_on_conn(
                    conn,
                    cockpit_db::secret_vault::SecretVaultKind::SealedState,
                    &vault_id,
                    Some(bytes.as_slice()),
                )
                .map_err(|error| anyhow::anyhow!(error))?;
            Ok(())
        })
        .await
        .map_err(internal)
}

/// Publish a Ready OAuth flow and its exact begin receipt under one SQLite
/// fence. A crash can therefore observe neither, or both; startup never has to
/// guess whether a returned authorize instruction had durable authority.
async fn commit_oauth_begin(
    ctx: &DaemonContext,
    flow_id: String,
    flow: DurableOAuthFlow,
    owner: String,
    client_operation_id: String,
    request_hash: [u8; 32],
    fencing_generation: i64,
    receipt: Response,
) -> std::result::Result<(), ErrorPayload> {
    let flow_bytes = zeroize::Zeroizing::new(serde_json::to_vec(&flow).map_err(internal)?);
    let receipt_json = serde_json::to_string(&receipt).map_err(internal)?;
    let vault = ctx.secret_vault.clone();
    let vault_id = oauth_flow_vault_id(&flow_id);
    ctx.db
        .transaction(move |conn| {
            vault
                .mutate_item_on_conn(
                    conn,
                    cockpit_db::secret_vault::SecretVaultKind::SealedState,
                    &vault_id,
                    Some(flow_bytes.as_slice()),
                )
                .map_err(|error| anyhow::anyhow!(error))?;
            let settled = conn.execute(
                "UPDATE local_operation_receipts
                 SET state='terminal_success',terminal_outcome_json=?5,
                     execution_expires_at_unix_ms=NULL,updated_at_unix_ms=?6
                 WHERE owner_digest=?1 AND client_operation_id=?2
                   AND request_hash=?3 AND fencing_generation=?4
                   AND state='executing'",
                rusqlite::params![
                    owner,
                    client_operation_id,
                    request_hash.as_slice(),
                    fencing_generation,
                    receipt_json,
                    chrono::Utc::now().timestamp_millis()
                ],
            )?;
            if settled != 1 {
                anyhow::bail!("OAuth begin lost its receipt fence");
            }
            Ok(())
        })
        .await
        .map_err(internal)?;
    if let Err(error) = ctx.publish_owner_redaction_table() {
        ctx.poison_redaction_publication(&error);
        tracing::error!(%error, "OAuth begin committed but redaction publication failed; daemon poisoned");
    }
    Ok(())
}

async fn commit_oauth_cancel(
    ctx: &DaemonContext,
    flow_id: Option<String>,
    delete_ready_flow: bool,
    begin_client_operation_id: String,
    owner: String,
    client_operation_id: String,
    request_hash: [u8; 32],
    fencing_generation: i64,
    response: &Response,
) -> std::result::Result<(), ErrorPayload> {
    let receipt_json = serde_json::to_string(response).map_err(internal)?;
    let vault = ctx.secret_vault.clone();
    ctx.db
        .transaction(move |conn| {
            if delete_ready_flow {
                let flow_id = flow_id
                    .as_deref()
                    .ok_or_else(|| anyhow::anyhow!("cancelled OAuth flow lost its identity"))?;
                let vault_id = oauth_flow_vault_id(flow_id);
                let current = vault
                    .get_item_on_conn(
                        conn,
                        cockpit_db::secret_vault::SecretVaultKind::SealedState,
                        &vault_id,
                    )
                    .map_err(|error| anyhow::anyhow!(error))?;
                let current: DurableOAuthFlow = serde_json::from_slice(current.as_slice())?;
                let (marker_owner, marker_begin_operation_id, exchanging_identity) = match current {
                    DurableOAuthFlow::Provider {
                        owner,
                        begin_client_operation_id,
                        ..
                    }
                    | DurableOAuthFlow::Mcp {
                        owner,
                        begin_client_operation_id,
                        ..
                    } => (owner, begin_client_operation_id, None),
                    DurableOAuthFlow::ProviderExchanging {
                        owner,
                        begin_client_operation_id,
                        completion_client_operation_id,
                        completion_request_hash,
                        completion_fencing_generation,
                        ..
                    }
                    | DurableOAuthFlow::McpExchanging {
                        owner,
                        begin_client_operation_id,
                        completion_client_operation_id,
                        completion_request_hash,
                        completion_fencing_generation,
                        ..
                    } => (
                        owner,
                        begin_client_operation_id,
                        Some((
                            completion_client_operation_id,
                            completion_request_hash,
                            completion_fencing_generation,
                        )),
                    ),
                    _ => anyhow::bail!("OAuth cancellation target is not live"),
                };
                if marker_owner != owner || marker_begin_operation_id != begin_client_operation_id {
                    anyhow::bail!("OAuth cancellation target identity does not match");
                }
                let terminal_error = ErrorPayload {
                    code: ErrorCode::Conflict,
                    message: "the OAuth flow was cancelled; start a new login".to_owned(),
                };
                let tombstone =
                    zeroize::Zeroizing::new(serde_json::to_vec(&DurableOAuthFlow::Cancelled {
                        owner: marker_owner,
                        begin_client_operation_id: marker_begin_operation_id,
                        terminal_error: terminal_error.clone(),
                        cancelled_at_unix_ms: oauth_wall_ms(),
                    })?);
                vault
                    .mutate_item_on_conn(
                        conn,
                        cockpit_db::secret_vault::SecretVaultKind::SealedState,
                        &vault_id,
                        Some(tombstone.as_slice()),
                    )
                    .map_err(|error| anyhow::anyhow!(error))?;
                if let Some((operation_id, exchange_hash, exchange_fence)) = exchanging_identity {
                    let exchange_error_json = serde_json::to_string(&terminal_error)?;
                    let settled_exchange = conn.execute(
                        "UPDATE local_operation_receipts
                         SET state='terminal_cancelled',terminal_outcome_json=?5,
                             execution_expires_at_unix_ms=NULL,updated_at_unix_ms=?6
                         WHERE owner_digest=?1 AND client_operation_id=?2
                           AND request_hash=?3 AND fencing_generation=?4
                           AND state='executing'",
                        rusqlite::params![
                            owner,
                            operation_id,
                            exchange_hash.as_slice(),
                            exchange_fence,
                            exchange_error_json,
                            oauth_wall_ms()
                        ],
                    )?;
                    if settled_exchange != 1 {
                        anyhow::bail!("OAuth cancellation lost the exact exchange receipt fence");
                    }
                }
            }
            let settled = conn.execute(
                "UPDATE local_operation_receipts
                 SET state='terminal_success',terminal_outcome_json=?5,
                     execution_expires_at_unix_ms=NULL,updated_at_unix_ms=?6
                 WHERE owner_digest=?1 AND client_operation_id=?2
                   AND request_hash=?3 AND fencing_generation=?4
                   AND state='executing'",
                rusqlite::params![
                    owner,
                    client_operation_id,
                    request_hash.as_slice(),
                    fencing_generation,
                    receipt_json,
                    chrono::Utc::now().timestamp_millis()
                ],
            )?;
            if settled != 1 {
                anyhow::bail!("OAuth cancellation lost its receipt fence");
            }
            Ok(())
        })
        .await
        .map_err(internal)?;
    if delete_ready_flow && let Err(error) = ctx.publish_owner_redaction_table() {
        ctx.poison_redaction_publication(&error);
        tracing::error!(%error, "OAuth cancellation committed but redaction publication failed; daemon poisoned");
    }
    Ok(())
}

async fn settle_failed_oauth_begin(
    ctx: &DaemonContext,
    owner: String,
    client_operation_id: String,
    request_hash: [u8; 32],
    fencing_generation: i64,
    error: &ErrorPayload,
) -> std::result::Result<ErrorPayload, ErrorPayload> {
    tracing::warn!(
        error_code = %error.code,
        error = %error.message,
        operation_id = %client_operation_id,
        "OAuth begin failed after receipt admission"
    );
    let terminal_error = ErrorPayload {
        code: error.code.clone(),
        message: "OAuth could not be started; inspect daemon diagnostics for details".to_owned(),
    };
    finish_local_operation_error(
        ctx,
        owner,
        client_operation_id,
        request_hash,
        fencing_generation,
        &terminal_error,
    )
    .await?;
    Ok(terminal_error)
}

/// Settle a failed one-shot exchange and remove its sealed claim atomically.
/// An Exchanging marker without an executing receipt is neither replayable nor
/// capacity-evictable, so the two pieces must never be torn across a crash.
async fn fail_oauth_exchange(
    ctx: &DaemonContext,
    flow_id: String,
    owner: String,
    client_operation_id: String,
    request_hash: [u8; 32],
    fencing_generation: i64,
    error: &ErrorPayload,
) -> std::result::Result<ErrorPayload, ErrorPayload> {
    tracing::warn!(
        error_code = %error.code,
        error = %error.message,
        operation_id = %client_operation_id,
        "OAuth exchange failed"
    );
    let terminal_error = ErrorPayload {
        code: error.code.clone(),
        message: if error.code == ErrorCode::Shutdown {
            "the daemon stopped before the OAuth exchange completed"
        } else {
            "the OAuth exchange was rejected; inspect daemon diagnostics for details"
        }
        .to_owned(),
    };
    let error_json = serde_json::to_string(&terminal_error).map_err(internal)?;
    let terminal_state = if error.code == ErrorCode::Shutdown {
        "terminal_cancelled"
    } else {
        "terminal_error"
    };
    let vault = ctx.secret_vault.clone();
    let terminal_error_for_return = terminal_error.clone();
    ctx.db
        .transaction(move |conn| {
            // A failed request is allowed to erase only the one-shot marker it
            // installed itself. In particular, an unknown or cross-owner flow
            // id must never become deletion authority over another principal's
            // live OAuth exchange.
            let vault_id = oauth_flow_vault_id(&flow_id);
            let owns_exact_claim = match vault.get_item_on_conn(
                conn,
                cockpit_db::secret_vault::SecretVaultKind::SealedState,
                &vault_id,
            ) {
                Ok(bytes) => {
                    let marker: DurableOAuthFlow = serde_json::from_slice(bytes.as_slice())?;
                    match marker {
                        DurableOAuthFlow::ProviderExchanging {
                            owner: marker_owner,
                            completion_client_operation_id,
                            completion_request_hash,
                            completion_fencing_generation,
                            ..
                        }
                        | DurableOAuthFlow::McpExchanging {
                            owner: marker_owner,
                            completion_client_operation_id,
                            completion_request_hash,
                            completion_fencing_generation,
                            ..
                        } => {
                            marker_owner == owner
                                && completion_client_operation_id == client_operation_id
                                && completion_request_hash == request_hash
                                && completion_fencing_generation == fencing_generation
                        }
                        _ => false,
                    }
                }
                Err(crate::secure_key::SecureKeyError::NotFound(_)) => false,
                Err(error) => return Err(anyhow::anyhow!(error)),
            };
            if owns_exact_claim {
                vault
                    .mutate_item_on_conn(
                        conn,
                        cockpit_db::secret_vault::SecretVaultKind::SealedState,
                        &vault_id,
                        None,
                    )
                    .map_err(|error| anyhow::anyhow!(error))?;
            }
            let changed = conn.execute(
                "UPDATE local_operation_receipts
                 SET state=?5,terminal_outcome_json=?6,
                     execution_expires_at_unix_ms=NULL,updated_at_unix_ms=?7
                 WHERE owner_digest=?1 AND client_operation_id=?2
                   AND request_hash=?3 AND fencing_generation=?4
                   AND state='executing'",
                rusqlite::params![
                    owner,
                    client_operation_id,
                    request_hash.as_slice(),
                    fencing_generation,
                    terminal_state,
                    error_json,
                    chrono::Utc::now().timestamp_millis()
                ],
            )?;
            if changed != 1 {
                anyhow::bail!("OAuth exchange failure lost its receipt fence");
            }
            Ok(())
        })
        .await
        .map_err(internal)?;
    Ok(terminal_error_for_return)
}

/// Reconcile token commits that became durable before their owner receipt was
/// acknowledged. The encrypted marker contains the exact admitted operation,
/// keyed request identity, fence, and secret-free terminal response, so this
/// runs before the generic interrupted-operation fail-closed sweep.
pub(super) async fn recover_committed_oauth_settlements(
    ctx: &DaemonContext,
) -> std::result::Result<(), ErrorPayload> {
    let item_ids = ctx
        .secret_vault
        .list_item_ids(cockpit_db::secret_vault::SecretVaultKind::SealedState)
        .map_err(|error| internal(anyhow::anyhow!(error)))?;
    for item_id in item_ids
        .into_iter()
        .filter(|id| id.starts_with("oauth-flow:"))
    {
        let flow_id = item_id.trim_start_matches("oauth-flow:");
        let Some(flow) = load_oauth_flow(ctx, flow_id)? else {
            continue;
        };
        let settlement = match flow {
            DurableOAuthFlow::Provider {
                owner,
                begin_client_operation_id,
                begin_request_hash,
                begin_fencing_generation,
                expires_at_unix_ms,
                ..
            }
            | DurableOAuthFlow::Mcp {
                owner,
                begin_client_operation_id,
                begin_request_hash,
                begin_fencing_generation,
                expires_at_unix_ms,
                ..
            } if oauth_wall_ms() >= expires_at_unix_ms => {
                expire_ready_oauth_flow(
                    ctx,
                    flow_id.to_owned(),
                    owner,
                    begin_client_operation_id,
                    begin_request_hash,
                    begin_fencing_generation,
                )
                .await?;
                None
            }
            DurableOAuthFlow::ProviderCommitted {
                owner,
                completion_client_operation_id,
                completion_request_hash,
                completion_fencing_generation,
                terminal_response,
                ..
            }
            | DurableOAuthFlow::McpCommitted {
                owner,
                completion_client_operation_id,
                completion_request_hash,
                completion_fencing_generation,
                terminal_response,
                ..
            } => Some((
                owner,
                completion_client_operation_id,
                completion_request_hash,
                completion_fencing_generation,
                terminal_response,
            )),
            DurableOAuthFlow::ProviderExchanging {
                owner,
                completion_client_operation_id,
                completion_request_hash,
                completion_fencing_generation,
                ..
            }
            | DurableOAuthFlow::McpExchanging {
                owner,
                completion_client_operation_id,
                completion_request_hash,
                completion_fencing_generation,
                ..
            } => {
                let interruption = ErrorPayload {
                    code: ErrorCode::Internal,
                    message: "the daemon restarted before the OAuth exchange completed; the one-time flow was cancelled"
                        .to_owned(),
                };
                let outcome_json = serde_json::to_string(&interruption).map_err(internal)?;
                let vault = ctx.secret_vault.clone();
                let vault_id = oauth_flow_vault_id(flow_id);
                ctx.db
                    .transaction(move |conn| {
                        let changed = conn.execute(
                            "UPDATE local_operation_receipts
                             SET state='terminal_cancelled',terminal_outcome_json=?5,
                                 execution_expires_at_unix_ms=NULL,updated_at_unix_ms=?6
                             WHERE owner_digest=?1 AND client_operation_id=?2
                               AND request_hash=?3 AND fencing_generation=?4
                               AND state='executing'",
                            rusqlite::params![
                                owner,
                                completion_client_operation_id,
                                completion_request_hash.as_slice(),
                                completion_fencing_generation,
                                outcome_json,
                                oauth_wall_ms()
                            ],
                        )?;
                        if changed != 1 {
                            anyhow::bail!(
                                "orphan OAuth exchange has no exact executing completion receipt"
                            );
                        }
                        vault
                            .mutate_item_on_conn(
                                conn,
                                cockpit_db::secret_vault::SecretVaultKind::SealedState,
                                &vault_id,
                                None,
                            )
                            .map_err(|error| anyhow::anyhow!(error))?;
                        Ok(())
                    })
                    .await
                    .map_err(internal)?;
                None
            }
            _ => None,
        };
        let Some((owner, operation_id, request_hash, fence, response)) = settlement else {
            continue;
        };
        finish_local_operation(
            ctx,
            owner,
            operation_id,
            request_hash,
            fence,
            response.as_ref(),
        )
        .await?;
        delete_oauth_flow(ctx, flow_id)?;
    }
    Ok(())
}

fn load_oauth_flow(
    ctx: &DaemonContext,
    flow_id: &str,
) -> std::result::Result<Option<DurableOAuthFlow>, ErrorPayload> {
    match ctx.secret_vault.get_item(
        cockpit_db::secret_vault::SecretVaultKind::SealedState,
        &oauth_flow_vault_id(flow_id),
    ) {
        Ok(bytes) => {
            let flow: DurableOAuthFlow =
                serde_json::from_slice(bytes.as_slice()).map_err(internal)?;
            // Expiry alone is not authority to destroy recovery evidence.
            // Admission maintenance removes only unreferenced Ready flows;
            // Exchanging/Committed and receipt-targeted rows remain
            // reconcilable across restart.
            Ok(Some(flow))
        }
        Err(crate::secure_key::SecureKeyError::NotFound(_)) => Ok(None),
        Err(error) => Err(internal(anyhow::anyhow!(error))),
    }
}

fn delete_oauth_flow(ctx: &DaemonContext, flow_id: &str) -> std::result::Result<(), ErrorPayload> {
    ctx.secret_vault
        .mutate_item(
            cockpit_db::secret_vault::SecretVaultKind::SealedState,
            &oauth_flow_vault_id(flow_id),
            None,
        )
        .map_err(|error| internal(anyhow::anyhow!(error)))?;
    Ok(())
}

// Provider device-code descriptors may poll for up to fifteen minutes. Keep
// their daemon-owned state alive through that advertised lifetime plus a
// bounded final token/commit margin.
const OAUTH_FLOW_TTL: Duration = Duration::from_secs(16 * 60);
const OAUTH_FLOW_GLOBAL_CAPACITY: usize = 64;
const OAUTH_FLOW_OWNER_CAPACITY: usize = 8;

fn local_operation_secret_request_hash<T: serde::Serialize>(
    ctx: &DaemonContext,
    domain: &'static [u8],
    request: &T,
) -> std::result::Result<[u8; 32], ErrorPayload> {
    let encoded = zeroize::Zeroizing::new(serde_json::to_vec(request).map_err(internal)?);
    Ok(ctx
        .secret_vault
        .keyed_request_identity(domain, encoded.as_slice()))
}

struct StoredProviderOAuthFlow {
    owner: String,
    begin_client_operation_id: String,
    authorize_url: String,
    user_code: Option<String>,
    created_at: Instant,
    flow: ProviderOAuthFlow,
}

struct StoredMcpOAuthFlow {
    owner: String,
    begin_client_operation_id: String,
    authorize_url: String,
    user_code: Option<String>,
    verification_uri: Option<String>,
    verification_uri_complete: Option<String>,
    created_at: Instant,
    flow: McpOAuthFlow,
}

enum McpOAuthFlow {
    Ready(McpOAuthPending),
    Completing {
        cancelled: std::sync::Arc<std::sync::atomic::AtomicBool>,
        /// The Complete operation that installed this fence. Timeout, cancel,
        /// and a second Complete must observe this same Arc; only that
        /// operation (or an explicit Cancel) may trip it on the way out.
        completion_client_operation_id: String,
    },
}

/// Daemon-owned OAuth state. Keeping this on the context prevents one daemon
/// instance or test from observing another's PKCE/device state, while the
/// bounded TTL/capacity prevents abandoned flows from growing without limit.
pub(crate) struct OAuthFlowStore {
    provider: tokio::sync::Mutex<std::collections::HashMap<String, StoredProviderOAuthFlow>>,
    mcp: tokio::sync::Mutex<std::collections::HashMap<String, StoredMcpOAuthFlow>>,
}

impl OAuthFlowStore {
    pub(crate) fn new() -> Self {
        Self {
            provider: tokio::sync::Mutex::new(std::collections::HashMap::new()),
            mcp: tokio::sync::Mutex::new(std::collections::HashMap::new()),
        }
    }

    fn trip_provider_cancellation(flow: &ProviderOAuthFlow) {
        if let ProviderOAuthFlow::Completing { cancelled } = flow {
            cancelled.store(true, std::sync::atomic::Ordering::SeqCst);
        }
    }

    fn purge_provider(flows: &mut std::collections::HashMap<String, StoredProviderOAuthFlow>) {
        let now = Instant::now();
        flows.retain(|_, flow| {
            let keep = now.duration_since(flow.created_at) <= OAUTH_FLOW_TTL;
            if !keep {
                Self::trip_provider_cancellation(&flow.flow);
            }
            keep
        });
    }

    fn trip_mcp_cancellation(flow: &McpOAuthFlow) {
        if let McpOAuthFlow::Completing { cancelled, .. } = flow {
            cancelled.store(true, std::sync::atomic::Ordering::SeqCst);
        }
    }

    fn purge_mcp(flows: &mut std::collections::HashMap<String, StoredMcpOAuthFlow>) {
        let now = Instant::now();
        flows.retain(|_, flow| {
            let keep = now.duration_since(flow.created_at) <= OAUTH_FLOW_TTL;
            if !keep {
                Self::trip_mcp_cancellation(&flow.flow);
            }
            keep
        });
    }

    /// Drop expired process-local mirrors without creating or replaying a
    /// flow. The durable sealed marker remains authoritative and is settled
    /// separately by [`maintain_durable_oauth_flows`].
    async fn maintain(&self) {
        Self::purge_provider(&mut *self.provider.lock().await);
        Self::purge_mcp(&mut *self.mcp.lock().await);
    }

    fn evict_oldest_provider(
        flows: &mut std::collections::HashMap<String, StoredProviderOAuthFlow>,
        owner: &str,
    ) {
        if let Some(id) = flows
            .iter()
            .filter(|(_, flow)| flow.owner == owner)
            .min_by_key(|(_, flow)| flow.created_at)
            .map(|(id, _)| id.clone())
        {
            if let Some(evicted) = flows.remove(&id) {
                Self::trip_provider_cancellation(&evicted.flow);
            }
        }
    }

    fn evict_oldest_mcp(
        flows: &mut std::collections::HashMap<String, StoredMcpOAuthFlow>,
        owner: &str,
    ) {
        if let Some(id) = flows
            .iter()
            .filter(|(_, flow)| flow.owner == owner)
            .min_by_key(|(_, flow)| flow.created_at)
            .map(|(id, _)| id.clone())
            && let Some(evicted) = flows.remove(&id)
        {
            Self::trip_mcp_cancellation(&evicted.flow);
        }
    }

    async fn insert_provider(
        &self,
        id: String,
        owner: String,
        begin_client_operation_id: String,
        authorize_url: String,
        user_code: Option<String>,
        flow: ProviderOAuthFlow,
    ) {
        let mut flows = self.provider.lock().await;
        Self::purge_provider(&mut flows);
        if flows.values().filter(|flow| flow.owner == owner).count() >= OAUTH_FLOW_OWNER_CAPACITY {
            Self::evict_oldest_provider(&mut flows, &owner);
        }
        if flows.len() >= OAUTH_FLOW_GLOBAL_CAPACITY
            && let Some(id) = flows
                .iter()
                .min_by_key(|(_, flow)| flow.created_at)
                .map(|(id, _)| id.clone())
        {
            if let Some(evicted) = flows.remove(&id) {
                Self::trip_provider_cancellation(&evicted.flow);
            }
        }
        flows.insert(
            id,
            StoredProviderOAuthFlow {
                owner,
                begin_client_operation_id,
                authorize_url,
                user_code,
                created_at: Instant::now(),
                flow,
            },
        );
    }

    async fn provider_started(
        &self,
        owner: &str,
        begin_id: &str,
    ) -> Option<(String, String, Option<String>)> {
        let mut flows = self.provider.lock().await;
        Self::purge_provider(&mut flows);
        flows
            .iter()
            .find(|(_, flow)| flow.owner == owner && flow.begin_client_operation_id == begin_id)
            .map(|(id, flow)| {
                (
                    id.clone(),
                    flow.authorize_url.clone(),
                    flow.user_code.clone(),
                )
            })
    }

    async fn claim_provider(
        &self,
        id: &str,
        owner: &str,
    ) -> Option<(
        ProviderOAuthReady,
        std::sync::Arc<std::sync::atomic::AtomicBool>,
    )> {
        let mut flows = self.provider.lock().await;
        Self::purge_provider(&mut flows);
        let stored = flows.get_mut(id).filter(|flow| flow.owner == owner)?;
        let ProviderOAuthFlow::Ready(ready) = &stored.flow else {
            return None;
        };
        let ready = ready.clone();
        let cancelled = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        stored.flow = ProviderOAuthFlow::Completing {
            cancelled: cancelled.clone(),
        };
        Some((ready, cancelled))
    }

    async fn restore_provider(&self, id: &str, owner: &str, flow: ProviderOAuthReady) {
        let mut flows = self.provider.lock().await;
        if let Some(stored) = flows.get_mut(id).filter(|flow| flow.owner == owner) {
            stored.flow = ProviderOAuthFlow::Ready(flow);
        }
    }

    async fn resolve_provider_id(
        &self,
        id: Option<&str>,
        begin_id: &str,
        owner: &str,
    ) -> Option<String> {
        let mut flows = self.provider.lock().await;
        Self::purge_provider(&mut flows);
        id.filter(|id| {
            flows.get(*id).is_some_and(|flow| {
                flow.owner == owner && flow.begin_client_operation_id == begin_id
            })
        })
        .map(ToOwned::to_owned)
        .or_else(|| {
            flows
                .iter()
                .find(|(_, flow)| flow.owner == owner && flow.begin_client_operation_id == begin_id)
                .map(|(id, _)| id.clone())
        })
    }

    async fn cancel_provider(&self, id: &str, owner: &str) -> bool {
        let mut flows = self.provider.lock().await;
        Self::purge_provider(&mut flows);
        let Some(stored) = flows.get(id).filter(|flow| flow.owner == owner) else {
            return false;
        };
        if let ProviderOAuthFlow::Completing { cancelled } = &stored.flow {
            cancelled.store(true, std::sync::atomic::Ordering::SeqCst);
        }
        flows.remove(id).is_some()
    }

    async fn remove_provider(&self, id: &str, owner: &str) -> bool {
        self.cancel_provider(id, owner).await
    }

    /// Remove an already-terminal flow without tripping its cancellation
    /// fence. Callers must hold the owner commit lock and must have observed a
    /// matching durable committed marker first.
    async fn remove_terminal_provider(&self, id: &str, owner: &str) -> bool {
        let mut flows = self.provider.lock().await;
        flows
            .get(id)
            .is_some_and(|flow| flow.owner == owner)
            .then(|| flows.remove(id))
            .flatten()
            .is_some()
    }

    async fn insert_mcp(
        &self,
        id: String,
        owner: String,
        begin_client_operation_id: String,
        authorize_url: String,
        flow: McpOAuthPending,
    ) {
        let mut flows = self.mcp.lock().await;
        Self::purge_mcp(&mut flows);
        if flows
            .get(&id)
            .is_some_and(|existing| matches!(existing.flow, McpOAuthFlow::Completing { .. }))
        {
            return;
        }
        if flows.values().filter(|flow| flow.owner == owner).count() >= OAUTH_FLOW_OWNER_CAPACITY {
            Self::evict_oldest_mcp(&mut flows, &owner);
        }
        if flows.len() >= OAUTH_FLOW_GLOBAL_CAPACITY
            && let Some(id) = flows
                .iter()
                .min_by_key(|(_, flow)| flow.created_at)
                .map(|(id, _)| id.clone())
            && let Some(evicted) = flows.remove(&id)
        {
            Self::trip_mcp_cancellation(&evicted.flow);
        }
        let (user_code, verification_uri, verification_uri_complete) =
            mcp_pending_device_display(&flow);
        flows.insert(
            id,
            StoredMcpOAuthFlow {
                owner,
                begin_client_operation_id,
                authorize_url,
                user_code,
                verification_uri,
                verification_uri_complete,
                created_at: Instant::now(),
                flow: McpOAuthFlow::Ready(flow),
            },
        );
    }

    async fn mcp_started(
        &self,
        owner: &str,
        begin_id: &str,
    ) -> Option<(
        String,
        String,
        Option<String>,
        Option<String>,
        Option<String>,
    )> {
        let mut flows = self.mcp.lock().await;
        Self::purge_mcp(&mut flows);
        flows
            .iter()
            .find(|(_, flow)| flow.owner == owner && flow.begin_client_operation_id == begin_id)
            .map(|(id, flow)| {
                (
                    id.clone(),
                    flow.authorize_url.clone(),
                    flow.user_code.clone(),
                    flow.verification_uri.clone(),
                    flow.verification_uri_complete.clone(),
                )
            })
    }

    async fn claim_mcp(
        &self,
        id: &str,
        owner: &str,
        completion_client_operation_id: &str,
    ) -> Option<(
        McpOAuthPending,
        std::sync::Arc<std::sync::atomic::AtomicBool>,
    )> {
        let mut flows = self.mcp.lock().await;
        Self::purge_mcp(&mut flows);
        let stored = flows.get_mut(id).filter(|flow| flow.owner == owner)?;
        // Ready-first, matching `claim_provider`: a second claim must not
        // replace the live Completing cancellation Arc with a dummy.
        let McpOAuthFlow::Ready(_) = &stored.flow else {
            return None;
        };
        let cancelled = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let McpOAuthFlow::Ready(pending) = std::mem::replace(
            &mut stored.flow,
            McpOAuthFlow::Completing {
                cancelled: cancelled.clone(),
                completion_client_operation_id: completion_client_operation_id.to_owned(),
            },
        ) else {
            unreachable!("Ready checked above")
        };
        Some((pending, cancelled))
    }

    async fn resolve_mcp_id(
        &self,
        id: Option<&str>,
        begin_id: &str,
        owner: &str,
    ) -> Option<String> {
        let mut flows = self.mcp.lock().await;
        Self::purge_mcp(&mut flows);
        id.filter(|id| {
            flows.get(*id).is_some_and(|flow| {
                flow.owner == owner && flow.begin_client_operation_id == begin_id
            })
        })
        .map(ToOwned::to_owned)
        .or_else(|| {
            flows
                .iter()
                .find(|(_, flow)| flow.owner == owner && flow.begin_client_operation_id == begin_id)
                .map(|(id, _)| id.clone())
        })
    }

    /// Cancel/abort path: trip whichever Completing fence is in the map, then
    /// drop it. Used by `CancelMcpOAuth`. Complete cleanup must use
    /// [`Self::remove_mcp_claimed_by`] so a losing Complete cannot abort the
    /// winner.
    async fn remove_mcp(&self, id: &str, owner: &str) -> bool {
        let mut flows = self.mcp.lock().await;
        Self::purge_mcp(&mut flows);
        let Some(stored) = flows.get(id).filter(|flow| flow.owner == owner) else {
            return false;
        };
        Self::trip_mcp_cancellation(&stored.flow);
        flows.remove(id).is_some()
    }

    /// Exit Completing only if this Complete operation installed the fence.
    /// Mirrors [`fail_oauth_exchange`]: a request that never owned the
    /// `McpExchanging` marker (or this Completing Arc) is not deletion
    /// authority over the winner.
    async fn remove_mcp_claimed_by(
        &self,
        id: &str,
        owner: &str,
        completion_client_operation_id: &str,
    ) -> bool {
        let mut flows = self.mcp.lock().await;
        Self::purge_mcp(&mut flows);
        let Some(stored) = flows.get(id).filter(|flow| flow.owner == owner) else {
            return false;
        };
        let owns_completing = matches!(
            &stored.flow,
            McpOAuthFlow::Completing {
                completion_client_operation_id: claimed_by,
                ..
            } if claimed_by == completion_client_operation_id
        );
        if !owns_completing {
            return false;
        }
        Self::trip_mcp_cancellation(&stored.flow);
        flows.remove(id).is_some()
    }

    async fn remove_terminal_mcp(&self, id: &str, owner: &str) -> bool {
        let mut flows = self.mcp.lock().await;
        flows
            .get(id)
            .is_some_and(|flow| flow.owner == owner)
            .then(|| flows.remove(id))
            .flatten()
            .is_some()
    }
}

fn oauth_owner(state: &MutableClientState) -> String {
    // OAuth and the rest of owner-scoped settings must share one durable
    // settlement namespace.  A connection-local/tag spelling made a lost
    // OAuth response unqueryable after reconnect even though the authenticated
    // principal was unchanged.
    stable_authenticated_principal(state)
}

/// Authentic "this request may perform LOCAL-HOST actions" signal for handlers
/// that would otherwise open a host browser, bind a host loopback listener, or
/// adopt the host's ambient environment secrets.
///
/// Both inputs are assigned by the daemon, never by the caller:
/// - `state.principal` is set at connection authentication from the transport
///   (a local unix-domain socket yields `ClientPrincipal::Owner`; a relay /
///   attempt-grant connection yields `ClientPrincipal::Remote` via the daemon's
///   verified constructors). A caller cannot present itself as `Owner`.
/// - `remote_operation` is produced only by `admit_remote_operation` from a
///   daemon-verified device actor binding; a genuine local owner always yields
///   `None` (admission short-circuits on `is_owner()`), and it cannot be forged.
///
/// Requiring BOTH (`is_owner()` AND no remote-operation context) can only make
/// the gate MORE restrictive, so it never downgrades a remote caller to local;
/// it additionally treats a remote-operation ledger dispatch as remote even when
/// the ledger path is exercised with an owner principal.
fn is_local_owner_action(
    state: &MutableClientState,
    #[cfg(feature = "remote")] remote_operation: Option<&super::RemoteOperationContext>,
) -> bool {
    state.principal.is_owner() && {
        #[cfg(feature = "remote")]
        {
            remote_operation.is_none()
        }
        #[cfg(not(feature = "remote"))]
        {
            true
        }
    }
}

/// Concurrent-lane analogue of [`is_local_owner_action`] over a shared snapshot.
/// Same semantics: a genuine local owner is the owner principal AND no
/// remote-operation ledger dispatch. A remoted owner (an owner principal
/// carrying a remote-operation context) is NOT a local-owner action, so it is
/// refused the raw `--include-sensitive` export exactly like any other remote.
#[cfg(feature = "remote")]
fn is_local_owner_action_shared(
    shared: &SharedClientState,
    remote_operation: Option<&super::RemoteOperationContext>,
) -> bool {
    shared.principal.is_owner() && remote_operation.is_none()
}

#[cfg(test)]
mod oauth_store_tests {
    use super::*;

    #[tokio::test]
    async fn provider_store_is_owner_scoped_and_bounded_per_owner() {
        let store = OAuthFlowStore::new();
        for index in 0..=OAUTH_FLOW_OWNER_CAPACITY {
            store
                .insert_provider(
                    format!("flow-{index}"),
                    "owner-a".to_string(),
                    format!("begin-{index}"),
                    "https://example.test".into(),
                    None,
                    ProviderOAuthFlow::Completing {
                        cancelled: std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false)),
                    },
                )
                .await;
        }

        assert!(
            store
                .resolve_provider_id(Some("flow-0"), "begin-0", "owner-a")
                .await
                .is_none()
        );
        assert!(
            store
                .resolve_provider_id(Some("flow-1"), "begin-1", "owner-b")
                .await
                .is_none()
        );
        assert_eq!(
            store
                .resolve_provider_id(Some("flow-8"), "begin-8", "owner-a")
                .await
                .as_deref(),
            Some("flow-8")
        );
    }

    #[tokio::test]
    async fn cancellation_fences_an_inflight_provider_completion() {
        let store = OAuthFlowStore::new();
        let cancelled = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        store
            .insert_provider(
                "flow".into(),
                "owner".into(),
                "begin".into(),
                "https://example.test".into(),
                None,
                ProviderOAuthFlow::Completing {
                    cancelled: cancelled.clone(),
                },
            )
            .await;
        assert!(store.cancel_provider("flow", "owner").await);
        assert!(cancelled.load(std::sync::atomic::Ordering::SeqCst));
    }

    fn test_mcp_pending(server: &str) -> McpOAuthPending {
        McpOAuthPending {
            project_root: "/tmp".into(),
            server: server.into(),
            profile: crate::mcp::config::DEFAULT_PROFILE.to_string(),
            flow: McpOAuthPendingFlow::Device {
                oauth: crate::mcp::config::OauthAuth::default(),
                device_code: "device-code".to_string().into(),
                interval_secs: 5,
                expires_in_secs: 60,
                user_code: "user-code".to_string().into(),
                verification_uri: "https://example.test/device".into(),
                verification_uri_complete: "https://example.test/device?code=user-code".into(),
            },
        }
    }

    #[tokio::test]
    async fn claim_mcp_preserves_completing_cancellation_fence_on_reentry() {
        let store = OAuthFlowStore::new();
        store
            .insert_mcp(
                "flow".into(),
                "owner".into(),
                "begin".into(),
                "https://example.test".into(),
                test_mcp_pending("server"),
            )
            .await;
        let (_, fence) = store
            .claim_mcp("flow", "owner", "winner")
            .await
            .expect("first claim takes Ready");
        assert!(
            store.claim_mcp("flow", "owner", "loser").await.is_none(),
            "second claim must not take an in-flight Completing flow"
        );
        assert!(
            !fence.load(std::sync::atomic::Ordering::SeqCst),
            "re-entry must not replace the live fence with a dummy"
        );
        store
            .insert_mcp(
                "flow".into(),
                "owner".into(),
                "begin".into(),
                "https://example.test".into(),
                test_mcp_pending("other"),
            )
            .await;
        assert!(
            store.claim_mcp("flow", "owner", "loser").await.is_none(),
            "recovery insert must not re-promote Ready over a live Completing fence"
        );
        assert!(store.remove_mcp("flow", "owner").await);
        assert!(
            fence.load(std::sync::atomic::Ordering::SeqCst),
            "cancel must trip the same Arc the first claim is watching"
        );
    }

    #[tokio::test]
    async fn remove_mcp_claimed_by_does_not_trip_winner_completing_fence() {
        let store = OAuthFlowStore::new();
        store
            .insert_mcp(
                "flow".into(),
                "owner".into(),
                "begin".into(),
                "https://example.test".into(),
                test_mcp_pending("server"),
            )
            .await;
        let (_, fence) = store
            .claim_mcp("flow", "owner", "winner")
            .await
            .expect("first claim takes Ready");
        assert!(
            !store.remove_mcp_claimed_by("flow", "owner", "loser").await,
            "a Complete that never claimed must not delete the winner's Completing entry"
        );
        assert!(
            !fence.load(std::sync::atomic::Ordering::SeqCst),
            "Complete Err cleanup must not trip a Completing fence this operation did not install"
        );
        assert!(
            store.claim_mcp("flow", "owner", "loser").await.is_none(),
            "loser cleanup must leave the winner's Completing fence in the map"
        );
        assert!(store.remove_mcp_claimed_by("flow", "owner", "winner").await);
        assert!(
            fence.load(std::sync::atomic::Ordering::SeqCst),
            "the operation that installed Completing must trip the same Arc on its own exit"
        );
    }

    #[test]
    fn complete_mcp_oauth_error_cleanup_does_not_trip_unowned_completing_fence() {
        let source = include_str!("dispatch.rs");
        let complete = source
            .split("Request::CompleteMcpOAuth {\n            client_operation_id,")
            .nth(1)
            .and_then(|rest| rest.split("Request::CancelMcpOAuth {").next())
            .expect("CompleteMcpOAuth branch");
        assert!(
            complete.contains("remove_mcp_claimed_by"),
            "Complete must only exit a Completing fence this operation installed"
        );
        assert!(
            !complete.contains("remove_mcp("),
            "unconditional remove_mcp trips any Completing, including a winner this Complete never claimed"
        );
    }

    #[test]
    fn durable_oauth_contract_is_expiring_fenced_and_secret_safe() {
        let source = include_str!("dispatch.rs");
        for required in [
            "created_at_unix_ms",
            "expires_at_unix_ms",
            "ProviderExchanging",
            "McpExchanging",
            "purge_durable_oauth_flows",
            "local_operation_secret_request_hash",
            "keyed_request_identity",
        ] {
            assert!(
                source.contains(required),
                "missing OAuth durability guard: {required}"
            );
        }
        assert!(source.contains("authorize_url: String::new()"));
        assert!(source.contains("user_code: None"));
        assert!(source.contains("provider-oauth/complete/v1\\0"));
        assert!(source.contains("mcp-oauth/complete/v1\\0"));
        assert!(source.contains("finish_local_operation_error("));
        let complete_provider = source
            .rsplit("Request::CompleteProviderOAuth {")
            .next()
            .and_then(|rest| rest.split("Request::CancelProviderOAuth {").next())
            .expect("CompleteProviderOAuth branch");
        assert!(
            !complete_provider.contains("MCP OAuth flow is not available for completion"),
            "CompleteProviderOAuth must not copy the MCP expiry predicate"
        );
    }
}

#[derive(Debug)]
