/// Poll interval for the until-idle auto-off watcher. Short enough that
/// the machine doesn't stay awake long after the last agent finishes,
/// long enough to be negligible overhead.
pub(super) const UNTIL_IDLE_POLL: std::time::Duration = std::time::Duration::from_secs(5);

/// Spawn the daemon's `until-idle` auto-off watcher. The daemon owns the
/// session workers / `ScheduleAuthority`, so it is the authority for "is an
/// agent running anywhere?". The watcher polls that and, once no agent is
/// running, releases the assertion and broadcasts the off-state to all
/// clients. It exits if the mode is no longer until-idle (a later
/// `on`/`off`/`toggle` superseded it) so a fresh `until-idle` can re-arm
/// without stacking watchers racing each other.
pub(super) fn spawn_until_idle_watcher(ctx: Arc<DaemonContext>) {
    tokio::spawn(async move {
        loop {
            tokio::time::sleep(UNTIL_IDLE_POLL).await;
            // Superseded (explicit on/off, or already auto-offed): stop.
            if !ctx.caffeinate.is_until_idle() {
                return;
            }
            let running = ctx.registry.any_agent_running();
            if let Some(applied) = ctx.caffeinate.idle_check(running) {
                ctx.broadcast_global(proto::Event::CaffeinateState {
                    active: applied.state.active,
                    lid_close_guaranteed: applied.lid_close_guaranteed,
                    message: None,
                });
                return;
            }
        }
    });
}

/// Poll interval for the idle-lock sweeper. Short relative to
/// [`crate::locks::LOCK_IDLE_TIMEOUT`] (5 min) so a reclaimable lock is
/// freed within a few seconds of crossing the threshold, but coarse enough
/// to be negligible overhead.
pub(super) const LOCK_SWEEP_POLL: std::time::Duration = std::time::Duration::from_secs(10);

/// Spawn the daemon's idle-lock sweeper
/// (implementation note). On each tick it asks the
/// single lock authority to reclaim any lock whose holder has been idle
/// past [`crate::locks::LOCK_IDLE_TIMEOUT`] — releasing it, invalidating the
/// §3c read-record, persisting the release, and waking blocked `read`
/// waiters so they proceed. Modeled on [`spawn_until_idle_watcher`]; runs
/// for the daemon's lifetime and exits when the daemon drains.
pub(crate) fn spawn_lock_sweeper(ctx: Arc<DaemonContext>) -> tokio::task::JoinHandle<()> {
    let locks = ctx.registry.locks();
    tokio::spawn(async move {
        loop {
            tokio::time::sleep(LOCK_SWEEP_POLL).await;
            if ctx.shutdown.is_draining() {
                return;
            }
            let now = chrono::Utc::now().timestamp();
            match locks.sweep_expired(now).await {
                Ok(reclaimed) if !reclaimed.is_empty() => {
                    tracing::info!(count = reclaimed.len(), "swept idle-expired locks");
                }
                Ok(_) => {}
                Err(e) => tracing::warn!(error = %e, "idle-lock sweep failed"),
            }
        }
    })
}

pub(super) fn code_root_contract_error(error: anyhow::Error) -> ErrorPayload {
    let message = error.to_string();
    let code = if message.contains("idempotency conflict") {
        ErrorCode::Conflict
    } else if message.contains("capability") || message.contains("closed") {
        ErrorCode::Authorization
    } else if message.contains("capacity") {
        ErrorCode::Conflict
    } else {
        ErrorCode::BadRequest
    };
    ErrorPayload { code, message }
}

/// Owns a capacity reservation across every await in a Code-root create or
/// attach route. Dispatch tasks are aborted when their connection closes, so
/// explicit error cleanup alone cannot release this boot-local permit.
struct CodeRootAttachmentReservationGuard<'a> {
    authority: &'a std::sync::Arc<std::sync::Mutex<crate::daemon::code_roots::CodeRootAuthorityV1>>,
    reservation: String,
}

impl<'a> CodeRootAttachmentReservationGuard<'a> {
    fn new(
        authority: &'a std::sync::Arc<
            std::sync::Mutex<crate::daemon::code_roots::CodeRootAuthorityV1>,
        >,
        reservation: String,
    ) -> Self {
        Self {
            authority,
            reservation,
        }
    }
}

impl Drop for CodeRootAttachmentReservationGuard<'_> {
    fn drop(&mut self) {
        crate::sync::lock_or_recover(self.authority)
            .release_attachment_reservation(&self.reservation);
    }
}

/// Owns a create, attach, or ACK idempotency fence while its dispatch future
/// may still own side effects. Once create has bound a newly-created root,
/// cancellation deliberately retains a bounded recovery association so an
/// exact retry resumes that root; a successful receipt explicitly finishes
/// it. The fence is separate from attachment capacity.
struct CodeRootRequestGuard<'a> {
    authority: &'a std::sync::Arc<std::sync::Mutex<crate::daemon::code_roots::CodeRootAuthorityV1>>,
    logical_client_id: proto::OpaqueAsciiId128V1,
    client_request_id: proto::OpaqueAsciiId128V1,
    route: &'static str,
}

struct CodeRootCreateRequestIdentity {
    logical_client_id: proto::OpaqueAsciiId128V1,
    client_request_id: proto::OpaqueAsciiId128V1,
}

impl<'a> CodeRootRequestGuard<'a> {
    fn new(
        authority: &'a std::sync::Arc<
            std::sync::Mutex<crate::daemon::code_roots::CodeRootAuthorityV1>,
        >,
        logical_client_id: proto::OpaqueAsciiId128V1,
        client_request_id: proto::OpaqueAsciiId128V1,
        route: &'static str,
    ) -> Self {
        Self {
            authority,
            logical_client_id,
            client_request_id,
            route,
        }
    }
}

impl Drop for CodeRootRequestGuard<'_> {
    fn drop(&mut self) {
        crate::sync::lock_or_recover(self.authority).abandon_code_root_request(
            &self.logical_client_id,
            &self.client_request_id,
            self.route,
        );
    }
}

/// Owns the in-flight first-wins fence until the dispatch future has either
/// completed or been dropped. This makes connection cancellation equivalent
/// to every explicit finish path.
struct CodeRootInterruptResolutionGuard<'a> {
    authority: &'a std::sync::Arc<std::sync::Mutex<crate::daemon::code_roots::CodeRootAuthorityV1>>,
    logical_client_id: proto::OpaqueAsciiId128V1,
    client_request_id: proto::OpaqueAsciiId128V1,
}

impl<'a> CodeRootInterruptResolutionGuard<'a> {
    fn new(
        authority: &'a std::sync::Arc<
            std::sync::Mutex<crate::daemon::code_roots::CodeRootAuthorityV1>,
        >,
        logical_client_id: proto::OpaqueAsciiId128V1,
        client_request_id: proto::OpaqueAsciiId128V1,
    ) -> Self {
        Self {
            authority,
            logical_client_id,
            client_request_id,
        }
    }
}

impl Drop for CodeRootInterruptResolutionGuard<'_> {
    fn drop(&mut self) {
        crate::sync::lock_or_recover(self.authority)
            .finish_interrupt_resolution(&self.logical_client_id, &self.client_request_id);
    }
}

fn code_root_interrupt_outcome_as_stored(
    outcome: proto::ResolveCodeRootInterruptResultV1,
) -> &'static str {
    match outcome {
        proto::ResolveCodeRootInterruptResultV1::Accepted => "accepted",
        proto::ResolveCodeRootInterruptResultV1::AlreadyResolvedSame => "already_resolved_same",
        proto::ResolveCodeRootInterruptResultV1::AlreadyResolvedOther => "already_resolved_other",
        proto::ResolveCodeRootInterruptResultV1::Cancelled => "cancelled",
        proto::ResolveCodeRootInterruptResultV1::Expired => "expired",
    }
}

fn code_root_interrupt_outcome_from_stored(
    outcome: &str,
) -> std::result::Result<proto::ResolveCodeRootInterruptResultV1, ErrorPayload> {
    match outcome {
        "accepted" => Ok(proto::ResolveCodeRootInterruptResultV1::Accepted),
        "already_resolved_same" => Ok(proto::ResolveCodeRootInterruptResultV1::AlreadyResolvedSame),
        "already_resolved_other" => {
            Ok(proto::ResolveCodeRootInterruptResultV1::AlreadyResolvedOther)
        }
        "cancelled" => Ok(proto::ResolveCodeRootInterruptResultV1::Cancelled),
        "expired" => Ok(proto::ResolveCodeRootInterruptResultV1::Expired),
        _ => Err(internal(anyhow::anyhow!(
            "invalid durable Code-root interrupt outcome"
        ))),
    }
}

async fn code_root_read_from_attached_response(
    ctx: &DaemonContext,
    response: Response,
) -> std::result::Result<proto::CodeRootReadV1, ErrorPayload> {
    let Response::Attached {
        session_id,
        session_entry_mode,
        short_id,
        project_root,
        project_id,
        active_agent,
        active_agent_path,
        foreground_target,
        active_subagent,
        active_model_state,
        history,
        removed_user_message_seqs: _,
        paused_work,
        repair_required,
        // The ACP Code-root projection deliberately does not transfer this
        // interactive, one-shot capability. It may only be consumed by the
        // attach response that issued it.
        resume_compaction_offer: _,
        daemon_version,
        compatible,
        env_baseline,
        env_session,
        env_drift,
        env_policy_applied,
        btw_fork,
    } = response
    else {
        return Err(internal(anyhow::anyhow!(
            "Code-root attach returned a non-attach response"
        )));
    };
    if session_entry_mode != proto::SessionEntryMode::Code {
        return Err(ErrorPayload {
            code: ErrorCode::BadRequest,
            message: "closed Code-root route resolved a non-Code session".into(),
        });
    }
    let title = ctx
        .db
        .get_session(session_id)
        .await
        .map_err(internal)?
        .and_then(|row| row.title);
    let attention = ctx
        .db
        .decision_attention_page(
            session_id,
            None,
            crate::db::agent_tree_decisions::MAX_AGENT_TREE_PAGE_SIZE,
        )
        .await
        .map_err(internal)?
        .entries
        .into_iter()
        .map(agent_attention_wire)
        .collect();
    Ok(proto::CodeRootReadV1 {
        root_id: proto::CodeRootIdV1(session_id),
        workspace_path: project_root,
        title,
        short_id,
        project_id,
        active_agent,
        active_agent_path,
        foreground_target,
        active_subagent,
        active_model_state,
        history,
        paused_work,
        repair_required,
        daemon_version,
        compatible,
        env_baseline,
        env_session,
        env_drift,
        env_policy_applied,
        btw_fork,
        attention,
    })
}

async fn code_root_read_snapshot(
    ctx: &DaemonContext,
    attached: &AttachedSession,
    root_id: proto::CodeRootIdV1,
) -> std::result::Result<proto::CodeRootReadV1, ErrorPayload> {
    let handle = &attached.handle;
    let row = ctx
        .db
        .get_session(root_id.0)
        .await
        .map_err(internal)?
        .ok_or_else(|| ErrorPayload {
            code: ErrorCode::UnknownSession,
            message: format!("unknown Code root {}", root_id.0),
        })?;
    if row.session_entry_mode != "code" {
        return Err(ErrorPayload {
            code: ErrorCode::BadRequest,
            message: "Code-root capability resolved a non-Code session".into(),
        });
    }
    let extended = handle.config_snapshot().extended;
    let foreground = handle.foreground_snapshot();
    let active_subagent = foreground.active_subagent.clone();
    let history = ctx
        .db
        .read(move |conn| {
            let root_agent =
                crate::daemon::session_worker::resolve_root_agent_conn(conn, root_id.0, &extended);
            crate::engine::rehydrate::history_snapshot_with_active_subagent_conn(
                conn,
                root_id.0,
                &root_agent,
                active_subagent.as_ref(),
            )
        })
        .await
        .map_err(internal)?;
    let attention = ctx
        .db
        .decision_attention_page(
            root_id.0,
            None,
            crate::db::agent_tree_decisions::MAX_AGENT_TREE_PAGE_SIZE,
        )
        .await
        .map_err(internal)?
        .entries
        .into_iter()
        .map(agent_attention_wire)
        .collect();
    let paused_work = ctx
        .db
        .paused_session_work(root_id.0)
        .await
        .map_err(internal)?
        .into_iter()
        .map(paused_work_to_proto)
        .collect();
    let active_agent = foreground
        .active_agent_path
        .last()
        .cloned()
        .filter(|name| !name.is_empty())
        .unwrap_or_else(|| handle.active_agent_name.clone());
    Ok(proto::CodeRootReadV1 {
        root_id,
        workspace_path: row.project_root,
        title: row.title,
        short_id: row.short_id.unwrap_or_default(),
        project_id: row.project_id,
        active_agent,
        active_agent_path: foreground.active_agent_path,
        foreground_target: Some(foreground.foreground_target),
        active_subagent: foreground.active_subagent,
        active_model_state: handle.authoritative_active_model_state(),
        history,
        paused_work,
        repair_required: handle.repair_required().map(Box::new),
        daemon_version: proto::DAEMON_VERSION.to_string(),
        compatible: true,
        env_baseline: None,
        env_session: None,
        env_drift: None,
        env_policy_applied: EnvDriftPolicy::Daemon,
        btw_fork: ctx
            .db
            .live_btw_fork_info(root_id.0)
            .await
            .map_err(internal)?
            .map(btw_info_to_proto),
        attention,
    })
}

/// Drain events emitted after an attach's durable snapshot was read.
///
/// A broadcast gap makes that snapshot stale: the queued lag marker must be
/// delivered before any retained post-gap events, so clients enter their normal
/// durable reattach/reconcile path before applying them.
pub(super) fn replay_attach_hydration_events(
    event_rx: &mut crate::daemon::EventReceiver,
    pending_replay: &mut Vec<proto::Event>,
    session_id: Uuid,
) {
    loop {
        match event_rx.try_recv() {
            Ok(envelope) => pending_replay.push(envelope.event),
            Err(broadcast::error::TryRecvError::Empty) => break,
            Err(broadcast::error::TryRecvError::Lagged(n)) => {
                // The history snapshot predates this loss, so it cannot be
                // treated as an authoritative attach projection. In
                // particular, a dropped `UserMessageRemoved` would otherwise
                // leave a retracted durable row rendered indefinitely. Match
                // the live-forwarder contract: deliver a typed lag marker
                // after the attach response so the client reattaches and
                // reconciles from its durable cursor. Keep draining the
                // receiver too, since events retained after the gap are still
                // useful while that resync is in flight.
                tracing::warn!(missed = n, %session_id, "attach hydration event replay lagged; reattach to resync");
                pending_replay.push(proto::Event::EventStreamLagged {
                    session_id: Some(session_id),
                    dropped: n,
                });
            }
            Err(broadcast::error::TryRecvError::Closed) => break,
        }
    }
}

#[allow(clippy::too_many_arguments)]
pub(super) async fn attach(
    state: &mut MutableClientState,
    ctx: &DaemonContext,
    code_root_create: Option<&CodeRootCreateRequestIdentity>,
    session_id: Option<Uuid>,
    since_seq: Option<i64>,
    project_root: Option<String>,
    initial_model: Option<crate::config::providers::ActiveModelRef>,
    no_sandbox: bool,
    interactive: bool,
    requested_session_entry_mode: Option<proto::SessionEntryMode>,
    model_override: Option<crate::config::providers::ActiveModelRef>,
    client_protocol_version: u32,
    env_snapshot: Option<EnvSnapshotWire>,
    env_policy: EnvDriftPolicy,
    principal: &ClientPrincipal,
    effects: &mut ClientRequestEffects,
) -> std::result::Result<Response, ErrorPayload> {
    // The client's `--no-sandbox` only governs sessions it *creates*
    // (sandboxing part 2). On resume of an existing session id the session
    // keeps its own runtime state, so the flag is ignored there.
    let client_no_sandbox = no_sandbox && session_id.is_none();
    // The plan-level model override (`cockpit run --model`) governs only
    // sessions this attach *creates*; on resume the worker is already
    // running, so the flag is ignored (mirrors `--no-sandbox`).
    let model_override = model_override.filter(|_| session_id.is_none());
    let project_root = project_root.map(PathBuf::from);

    // Claim an in-memory lazy session before consulting SQLite. The worker
    // persists the row before durable lifecycle setup; until then only the
    // registry owns its identity, project root, and immutable setup mode.
    // Authorization has already limited this path to the local owner.
    let live_claim = match session_id {
        Some(id) => ctx
            .registry
            .claim_live_attach_if_present(id)
            .await
            .map_err(internal)?,
        None => None,
    };
    let mut session_entry_mode = match (session_id, requested_session_entry_mode) {
        // Existing-session input is checked against the durable row below.
        // The placeholder is replaced before the registry sees it.
        (Some(_), Some(_)) => proto::SessionEntryMode::Code,
        (None, None) => {
            return Err(ErrorPayload {
                code: ErrorCode::BadRequest,
                message: "new-session attach requires session_entry_mode".into(),
            });
        }
        (None, Some(mode)) => mode,
        // Durable mode is loaded with the project root below, before the
        // registry can expose a resumed/live worker to this client.
        (Some(_), None) => proto::SessionEntryMode::Code,
    };
    let cfg_root = match (session_id, live_claim.as_ref(), &project_root) {
        (Some(_), Some(claim), _) => {
            let mode = claim.session_entry_mode();
            if let Some(requested) = requested_session_entry_mode
                && mode != proto::SessionEntryMode::Code
                && requested != mode
            {
                return Err(ErrorPayload {
                    code: ErrorCode::BadRequest,
                    message: format!(
                        "session entry mode conflict: session is {}, attach requested {}",
                        mode.as_str(),
                        requested.as_str()
                    ),
                });
            }
            // The live worker is the sole source of lazy-session identity;
            // never accept a caller project root or setup mode here.
            session_entry_mode = mode;
            Some(claim.project_root().clone())
        }
        (Some(id), None, _) => match ctx.db.get_session(id).await {
            Ok(Some(row)) => {
                let mode = match row.session_entry_mode.as_str() {
                    "code" => proto::SessionEntryMode::Code,
                    "assistant" => proto::SessionEntryMode::Assistant,
                    "computer" => proto::SessionEntryMode::Computer,
                    invalid => {
                        return Err(ErrorPayload {
                            code: ErrorCode::BadRequest,
                            message: format!("invalid persisted session entry mode {invalid:?}"),
                        });
                    }
                };
                if let Some(requested) = requested_session_entry_mode
                    && mode != proto::SessionEntryMode::Code
                    && requested != mode
                {
                    return Err(ErrorPayload {
                        code: ErrorCode::BadRequest,
                        message: format!(
                            "session entry mode conflict: session is {}, attach requested {}",
                            mode.as_str(),
                            requested.as_str()
                        ),
                    });
                }
                // Rebind from daemon storage, never from caller input.
                session_entry_mode = mode;
                Some(PathBuf::from(row.project_root))
            }
            Ok(None) => {
                return Err(ErrorPayload {
                    code: ErrorCode::UnknownSession,
                    message: format!("unknown session {id}"),
                });
            }
            Err(e) => return Err(internal(e)),
        },
        (None, _, Some(root)) => Some(root.clone()),
        (None, _, None) => {
            return Err(ErrorPayload {
                code: ErrorCode::BadRequest,
                message: "attach requires session_id or project_root".into(),
            });
        }
    };

    let cfg_root = cfg_root.expect("resolved above");
    // Terminal results for transactions this attach converged. Delivered
    // through the worker below, once a handle exists to stamp the generation.
    let recovered_default_transactions;
    // Resolution barrier: finish any pending effective-default transaction —
    // including its guarded session half — before this attach can serve a
    // session or default snapshot. Failing closed here is deliberate: a
    // journal that cannot be converged means the durable default and the
    // session model may disagree, which is exactly what attach must not show.
    {
        let trust_policy =
            crate::config::trust::resolve_workspace_trust_policy_from_db(&ctx.db, &cfg_root)
                .await
                .ok();
        recovered_default_transactions =
            crate::daemon::effective_default_recovery::recover_effective_default_journals(
                &ctx.db,
                &cfg_root,
                trust_policy,
            )
            .await
            .map_err(|error| {
            tracing::error!(%error, "effective-default journal recovery failed during attach");
            ErrorPayload {
                code: ErrorCode::InvalidConfig,
                    message:
                        "a pending default-model update could not be recovered; run `cockpit doctor` \
                         to inspect the pending journal for this configuration layer"
                            .to_string(),
                }
            })?;
    }
    let remote_readonly_attach = !principal.is_owner()
        && !principal.can_agent_write_project(&cfg_root.to_string_lossy())
        && principal.can_agent_read_project(&cfg_root.to_string_lossy());
    let client_no_sandbox = client_no_sandbox && !remote_readonly_attach;
    // Cross-process freshness invariant: no trust or session lookup may be
    // cached across requests without an invalidation path. The registry makes
    // the atomic live-vs-start decision: a live worker keeps its snapshotted
    // policy, while every newly-created/resumed worker reads through SQLite
    // after winning its start claim. Thus a trust flip affects the next worker
    // creation and never retroactively mutates a running session.
    // An environment snapshot is process-authority input: it influences
    // provider credential expansion, subprocess PATH lookup, and redaction.
    // Remote principals may attach to sessions but never supply that ambient
    // authority. Authorization rejects the global UpdateDaemon mutation; this
    // dispatch boundary also ignores every non-owner snapshot/policy so a
    // future authz regression cannot inject values into a cold worker.
    let (client_snapshot, env_policy) = if principal.is_owner() {
        (env_snapshot.map(EnvSnapshot::from_wire), env_policy)
    } else {
        (None, EnvDriftPolicy::Daemon)
    };
    let (session_env, env_baseline_meta, env_session_meta, env_drift, env_policy_applied) =
        select_session_env(ctx, client_snapshot, env_policy)?;

    let handle = if let Some(claim) = live_claim {
        // Validation above has proved the optional client assertion equals the
        // claim's daemon-owned mode. Only now may this reattach reclaim its
        // released session locks. The generation check makes any close/replace
        // race content-free: retry so the next request resolves the current
        // live worker or durable row instead of using stale mode/root facts.
        let Some(handle) = ctx
            .registry
            .activate_claimed_live_session(claim)
            .await
            .map_err(internal)?
        else {
            return Err(ErrorPayload {
                code: ErrorCode::Conflict,
                message: "session changed while attaching; retry the attach".into(),
            });
        };
        handle
    } else {
        ctx.registry
            .attach(
                session_id,
                project_root,
                initial_model,
                client_no_sandbox,
                model_override.as_ref(),
                session_env,
                session_entry_mode,
            )
            .await
            .map_err(|error| {
                if error
                    .downcast_ref::<crate::daemon::registry::SessionEntryModeConflict>()
                    .is_some()
                {
                    ErrorPayload {
                        code: ErrorCode::BadRequest,
                        message: error.to_string(),
                    }
                } else if error
                    .downcast_ref::<crate::daemon::registry::SessionAttachRetry>()
                    .is_some()
                    || error
                        .downcast_ref::<crate::daemon::registry::SessionTerminalCleanupRetry>()
                        .is_some()
                {
                    ErrorPayload {
                        code: ErrorCode::Conflict,
                        message: error.to_string(),
                    }
                } else {
                    workspace_trust_error(error)
                }
            })?
    };
    // Bind a newly-created Code root to its request identity as soon as the
    // worker exists.  Everything below this point may hydrate projections or
    // be cancelled by the transport, but an exact retry can now resume this
    // root instead of creating another one.
    if let Some(pending) = code_root_create {
        crate::sync::lock_or_recover(&ctx.code_root_authority)
            .bind_created_root(
                &pending.logical_client_id,
                &pending.client_request_id,
                proto::CodeRootIdV1(handle.session_id),
            )
            .map_err(code_root_contract_error)?;
    }
    // Attach-only projections use the policy snapshot of the handle that the
    // registry actually returned. This is safe for both branches: live
    // workers retain their original policy, while newly-started workers have
    // already performed the post-claim DB read-through.
    // Capability-backed default journals deliberately survived the ambient
    // pre-attach scan. Only a live worker has the exact retained authority
    // required to recover/refresh/receipt them. A failure remains pending and
    // does not make an otherwise valid attachment disappear.
    if let Err(error) = recover_retained_defaults_for_attached_worker(ctx, &handle).await {
        tracing::warn!(%error, session_id = %handle.session_id, "retained default-model recovery remains pending after attach");
    }
    // The worker exists now, so any *ambient* transaction this attach
    // converged can be delivered as a correlated terminal result.
    crate::daemon::effective_default_recovery::deliver_recovered_terminals(
        ctx,
        recovered_default_transactions,
    )
    .await
    .map_err(internal)?;
    let config_snapshot = handle.config_snapshot();
    let extended_cfg = config_snapshot.extended.clone();

    if session_id.is_none()
        && let Some(tag) = principal.tag()
    {
        handle
            .set_created_by_principal(Some(tag))
            .map_err(internal)?;
    }
    // A per-run daemon can disappear as soon as its client exits. Make the
    // session row durable before returning its id so another daemon process
    // can always find it through the normal DB-backed resume path.
    if session_id.is_none() && ctx.paths.ephemeral {
        handle.persist_if_needed().map_err(internal)?;
    }
    if remote_readonly_attach {
        let caps = current_host_capability_snapshot(ctx);
        let _ = handle.set_sandbox(
            Some(crate::tools::sandbox_mode::SandboxMode::Sandbox),
            None,
            &caps,
        );
        handle.set_approval_mode(crate::config::extended::ApprovalMode::Manual);
    }

    // Replace any prior attachment. Register this client with the worker's
    // interactive-client counter when it can answer interrupts (the loop
    // guard reads that count for headless detection). Building the guard
    // before the old `state.attached` is replaced means a re-attach by the
    // same client transiently holds two guards, never zero — the count
    // can't briefly read headless mid-swap.
    let mut event_rx = handle.subscribe();
    let interactive_guard = if interactive {
        Some(handle.register_interactive_client())
    } else {
        None
    };
    let session_id = handle.session_id;
    // Reuse the worker's attach-time root proof.  Capturing a fresh proof here
    // would permit an A→B→A swap between worker construction and client
    // attachment, leaving setup authorization bound to A while the worker had
    // already adopted B's provider snapshot.
    let workspace_identity = handle.workspace_root_authority.attached_root.clone();

    // Read/unread marker (GOALS §17f): the session just became active for
    // this client, so everything the agent produced up to now is "seen."
    // Best-effort — a marker write failure must not block the attach.
    if let Err(e) = handle.mark_viewed() {
        tracing::warn!(error = %e, %session_id, "mark_session_viewed failed");
    }

    let foreground = handle.foreground_snapshot();
    let project_root = handle.project_root.to_string_lossy().into_owned();
    let active_agent = foreground
        .active_agent_path
        .last()
        .cloned()
        .filter(|name| !name.is_empty())
        .unwrap_or_else(|| handle.active_agent_name.clone());
    // Source identity from the live session, not a DB read: a freshly
    // created session is deferred-persistence (session-id-display-and-lazy-
    // persist) and has no `sessions` row yet, so `get_session` would miss.
    let project_id = handle.project_id();
    let short_id = handle.short_id();
    let session_entry_mode = handle.session_entry_mode();
    let active_model_state = handle.authoritative_active_model_state().map(|mut state| {
        state.generation = 0;
        state
    });

    drain_client_attachment_ownership(state, ctx, "reattach").await?;
    state.upload_limits = extended_cfg.daemon.uploads.into();
    state.attached = Some(AttachedSession {
        handle,
        code_root_capability: None,
        workspace_identity: Some(workspace_identity),
        _interactive_guard: interactive_guard,
    });

    // Hydrate the queue and gitignore read-allowlist for this client. The
    // just-subscribed `event_rx` receives both full-list replacements, so a
    // late-opened or reconnecting TUI — and any second concurrent client —
    // learns state established before it attached, not only later mutations.
    // Queue replay intentionally includes an empty snapshot; gitignore replay
    // sends only the allow-set.
    if let Some(att) = state.attached.as_ref() {
        att.handle
            .broadcast_queue_snapshot()
            .await
            .map_err(internal)?;
        att.handle.broadcast_gitignore_allow();
        att.handle.broadcast_active_interrupt().await;
        att.handle.broadcast_sandbox_state();
        att.handle.broadcast_sandbox_escalation();
        att.handle.broadcast_sandbox_unavailable_or_probe();
        att.handle.broadcast_config_snapshot();
    }

    // Full chronological history snapshot (user messages + assistant turns +
    // tool calls) for the attached session, so a resuming TUI repopulates the
    // whole prior transcript (implementation note). Run the
    // scan-shaped attach reads on one blocking DB worker and one mutex
    // acquisition, while preserving the single history projection source.
    let db = ctx.db.clone();
    let extended_cfg_for_attach = extended_cfg.clone();
    let active_subagent_for_attach = foreground.active_subagent.clone();
    let (mut history, paused_work, replay_max_seq, removed_user_message_seqs): (
        Vec<proto::HistoryEntry>,
        Vec<proto::PausedWorkSummary>,
        Option<i64>,
        Vec<i64>,
    ) = db
        .read(move |conn| {
            let root_agent = crate::daemon::session_worker::resolve_root_agent_conn(
                conn,
                session_id,
                &extended_cfg_for_attach,
            );
            let (history, replay_max_seq, removed_user_message_seqs) = if let Some(since_seq) = since_seq {
                let replay_rows =
                    crate::db::Db::list_session_events_since_conn(conn, session_id, since_seq)?;
                let replay_max_seq = replay_rows.iter().map(|row| row.seq).max();
                // A retraction deletes its user row, so normal transcript
                // projection has nothing to render for it. Preserve the
                // tombstone's target identity as a narrow replay operation:
                // clients remove only this proven-stale row and never infer
                // deletion from an entry merely being absent from a snapshot.
                let removed_user_message_seqs = replay_rows
                    .iter()
                    .filter(|row| row.kind == "user_message_retracted")
                    .filter_map(|row| {
                        row.data
                            .get("retracted_seq")
                            .and_then(serde_json::Value::as_i64)
                    })
                    .collect();
                let history = crate::engine::rehydrate::history_snapshot_from_events_conn(
                    conn,
                    session_id,
                    &root_agent,
                    active_subagent_for_attach.as_ref(),
                    replay_rows,
                )?;
                (history, replay_max_seq, removed_user_message_seqs)
            } else {
                // A full snapshot is merged with retained paged/live rows by
                // remote clients, so it must carry all durable retraction
                // targets as well. Absence from a snapshot is never treated
                // as deletion: only these tombstone-backed identities remove
                // a cached user row.
                let snapshot_rows = crate::db::Db::list_session_events_conn(conn, session_id)?;
                let removed_user_message_seqs = snapshot_rows
                        .iter()
                        .filter(|row| row.kind == "user_message_retracted")
                        .filter_map(|row| {
                            row.data
                                .get("retracted_seq")
                                .and_then(serde_json::Value::as_i64)
                        })
                        .collect();
                let history = crate::engine::rehydrate::history_snapshot_from_events_conn(
                    conn,
                    session_id,
                    &root_agent,
                    active_subagent_for_attach.as_ref(),
                    snapshot_rows,
                )
                .unwrap_or_else(|e| {
                    tracing::warn!(error = %e, %session_id, "building attach history snapshot failed; sending empty history");
                    Vec::new()
                });
                (history, None, removed_user_message_seqs)
            };
            let paused_work = crate::db::Db::paused_session_work_conn(conn, session_id)?
                .into_iter()
                .map(paused_work_to_proto)
                .collect();
            Ok((
                history,
                paused_work,
                replay_max_seq,
                removed_user_message_seqs,
            ))
        })
        .await
        .map_err(internal)?;
    if !paused_work.is_empty()
        && let Some(att) = state.attached.as_ref()
    {
        att.handle.broadcast_notice(
            "paused work is waiting for resume or cancel after daemon restart".to_string(),
        );
    }

    replay_attach_hydration_events(&mut event_rx, &mut state.pending_replay, session_id);
    effects.session_event_rx = Some(event_rx);

    history = if let Some(att) = state.attached.as_ref() {
        let redact = att.handle.redaction_table();
        scrub_history_for_principal(&state.principal, history, &redact)
    } else {
        history
    };
    let attached_removed_user_message_seqs = if replay_max_seq.is_none() {
        removed_user_message_seqs.clone()
    } else {
        Vec::new()
    };
    if let Some(max_seq) = replay_max_seq {
        if !history.is_empty() || !removed_user_message_seqs.is_empty() {
            state.pending_replay.push(proto::Event::HistoryReplay {
                session_id,
                entries: history,
                removed_user_message_seqs,
                max_seq,
            });
        }
        history = Vec::new();
    }
    let btw_fork = ctx
        .db
        .live_btw_fork_info(session_id)
        .await
        .map_err(internal)?
        .map(btw_info_to_proto);

    Ok(Response::Attached {
        session_id,
        session_entry_mode,
        short_id,
        project_root,
        project_id,
        active_agent,
        active_agent_path: foreground.active_agent_path,
        foreground_target: Some(foreground.foreground_target),
        active_subagent: foreground.active_subagent,
        active_model_state,
        history,
        removed_user_message_seqs: attached_removed_user_message_seqs,
        paused_work,
        repair_required: state
            .attached
            .as_ref()
            .and_then(|att| att.handle.repair_required())
            .map(Box::new),
        // An away-resume offer is minted and consumed through the driver work
        // protocol, not reconstructed during an ordinary attach. In
        // particular, an ACP Code-root attach must never acquire that
        // one-shot interactive authority by replaying this response.
        resume_compaction_offer: None,
        daemon_version: proto::DAEMON_VERSION.to_string(),
        compatible: proto::is_protocol_compatible(client_protocol_version),
        env_baseline: Some(env_baseline_meta),
        env_session: Some(env_session_meta),
        env_drift: env_drift.map(Box::new),
        env_policy_applied,
        btw_fork,
    })
}

pub(super) fn select_session_env(
    ctx: &DaemonContext,
    client_snapshot: Option<EnvSnapshot>,
    policy: EnvDriftPolicy,
) -> std::result::Result<
    (
        EnvSnapshot,
        EnvSnapshotMeta,
        EnvSnapshotMeta,
        Option<EnvDiffSummary>,
        EnvDriftPolicy,
    ),
    ErrorPayload,
> {
    let Some(client_snapshot) = client_snapshot else {
        let baseline = ctx
            .env_baseline
            .read()
            .unwrap_or_else(|poisoned| poisoned.into_inner())
            .clone();
        let meta = baseline.meta();
        return Ok((baseline, meta.clone(), meta, None, EnvDriftPolicy::Daemon));
    };

    let baseline = ctx
        .env_baseline
        .read()
        .unwrap_or_else(|poisoned| poisoned.into_inner())
        .clone();
    let drift = diff_summary(&baseline, &client_snapshot).filter(EnvDiffSummary::meaningful);
    if matches!(policy, EnvDriftPolicy::ErrorOnDrift) && drift.is_some() {
        return Err(ErrorPayload {
            code: ErrorCode::BadRequest,
            message: "client environment differs from daemon baseline".to_string(),
        });
    }

    let chosen = match policy {
        EnvDriftPolicy::Daemon | EnvDriftPolicy::ErrorOnDrift => baseline.clone(),
        EnvDriftPolicy::Client => client_snapshot.clone(),
        EnvDriftPolicy::UpdateDaemon => {
            {
                let mut guard = ctx
                    .env_baseline
                    .write()
                    .unwrap_or_else(|poisoned| poisoned.into_inner());
                *guard = client_snapshot.clone();
            }
            client_snapshot.clone()
        }
    };
    let baseline_meta = if matches!(policy, EnvDriftPolicy::UpdateDaemon) {
        client_snapshot.meta()
    } else {
        baseline.meta()
    };
    let session_meta = chosen.meta();
    if matches!(policy, EnvDriftPolicy::Daemon)
        && let Some(diff) = drift.clone()
    {
        ctx.broadcast_global(proto::Event::EnvDriftWarning {
            baseline: baseline.meta(),
            candidate: client_snapshot.meta(),
            diff,
            policy,
        });
    }
    Ok((chosen, baseline_meta, session_meta, drift, policy))
}

pub(super) fn active_model_trigger_from_proto(
    trigger: proto::ActiveModelSwitchTrigger,
) -> crate::session::ModelSwitchTrigger {
    match trigger {
        proto::ActiveModelSwitchTrigger::Picker => crate::session::ModelSwitchTrigger::Picker,
        proto::ActiveModelSwitchTrigger::Quick => crate::session::ModelSwitchTrigger::Quick,
        proto::ActiveModelSwitchTrigger::Cycle => crate::session::ModelSwitchTrigger::Cycle,
        proto::ActiveModelSwitchTrigger::Daemon => crate::session::ModelSwitchTrigger::Daemon,
    }
}

pub(super) fn goal_to_proto(goal: crate::db::session_goals::SessionGoal) -> proto::GoalSummary {
    proto::GoalSummary {
        id: goal.id,
        session_id: goal.session_id,
        project_id: goal.project_id,
        objective: goal.objective,
        context: goal.context,
        disposition: goal.disposition,
        phase: goal.phase,
        resume_phase: goal.resume_phase,
        pause_reason: goal.pause_reason,
        contract_available: goal.contract.is_some(),
        latest_gap_or_blocker: goal
            .unresolved_gaps
            .first()
            .cloned()
            .or(goal.blocker_key.clone()),
        verification_attempts: goal.verification_rounds,
        max_verification_attempts: serde_json::from_str::<serde_json::Value>(
            &goal.resolved_policy_json,
        )
        .ok()
        .and_then(|value| {
            value
                .get("maxVerificationAttempts")
                .and_then(serde_json::Value::as_u64)
        })
        .unwrap_or(4),
        attempt_generation: goal.attempt_generation,
        token_budget: goal.token_budget,
        tokens_used: goal.tokens_used,
        remaining_tokens: goal.token_budget.saturating_sub(goal.tokens_used),
        elapsed_active_ms: goal.elapsed_active_ms,
        lifecycle_history: goal.lifecycle_history,
        blocked_attempts: goal.blocked_attempts,
        last_read_at: goal.last_read_at,
        created_at: goal.created_at,
        updated_at: goal.updated_at,
    }
}

pub(super) fn assistant_to_proto(
    row: crate::db::assistants::AssistantRow,
) -> proto::AssistantSummary {
    proto::AssistantSummary {
        registration_revision: crate::assistants::registration_revision(&row),
        name: row.name,
        created_at: row.created_at_unix_ms,
        home_dir: row.home_dir,
        config_json: row.config_json,
        definition_presentation_hash: None,
        definition_markdown: None,
        definition_revision: None,
        definition_diagnostic: None,
        projection_digest: String::new(),
    }
}

fn soul_edit_mode_to_wire(mode: crate::assistants::identity::SoulEditMode) -> &'static str {
    match mode {
        crate::assistants::identity::SoulEditMode::HumanOnly => "human_only",
        crate::assistants::identity::SoulEditMode::ApproveProposals => "approve_proposals",
        crate::assistants::identity::SoulEditMode::Autonomous => "autonomous",
    }
}

fn assistant_snapshot_to_proto(
    snapshot: crate::assistants::AssistantSnapshot,
) -> proto::AssistantSummary {
    let mut summary = assistant_to_proto(snapshot.row);
    summary.definition_markdown = snapshot.definition_markdown;
    summary.definition_revision = snapshot.definition_revision;
    summary.definition_diagnostic = snapshot.definition_diagnostic;
    summary
}

